        if k >= n or text[k] != "]":
            raise _JSExprFail("F530 bound target non-empty receiver")
        k = _js_skip_ws(text, k + 1)
        if k >= n or text[k] != ".":
            raise _JSExprFail("F530 bound target without member dot")
        k = _js_skip_ws(text, k + 1)
