    if not isinstance(then_lit, str) or isinstance(then_lit, _JSNumStr):
        raise _JSExprFail("F720 then not a plain string")
    k = _js_skip_ws(text, k)
    if k >= n or text[k] != ":":
        raise _JSExprFail("F720 ternary without :")
