            sj = _js_skip_ws(text, sj)
            if sj < n and text[sj] in "'\"":
                term, sj = _js_parse_string(text, sj)
                _js_f672_charge(state)
            else:
                _mc_saved_parts = state["parts"]
                _mc_saved_ops = state["ops"]
