        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
