def _js_parse_f788_aggerrors_iife(text, i, depth, state):
    """Parse `(function(){DECL e=[new] AggregateError([LITS](,'MSG')?);return ADD;})()` (F788).

    The decoder has no AggregateError production:
      `(function(){var e=new AggregateError(['f1'],'x');return e.errors[0]+'f2';})()`
      `(function(){var e=new AggregateError(['f1','f2'],'x');return e.errors.join('');})()`
    node-evaluate (v24.20.0) to the exact credential while the
    decoder produces zero variants. Node-exact desugar: the
    errors array literal is copied element-wise into the fresh
    `.errors` array (string-literal elements only); the message
    is the second argument or `''`; the return additive resolves
    `e.errors[INT]` (in-range), `e.errors.join('SEP')` /
    `e.errors.join()` (default `,`), a bare `e.errors`
    (Array-toString, `,`-joined), and `e.message` against the
    tracked literals. `[new]` is optional -- the engine accepts
    both spellings.

    Bounds (all fail closed -- rejected, never mis-decoded): a
    non-literal errors source, holes, non-string elements, an
    out-of-range index, a non-literal join separator, a
    reassigned `.errors`, extra statements, a missing message
    read of another member. On miss the F452 budgets are restored
    (wave-383 lesson). Returns (value, next_index), or None.
    Never evals.
    """
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    saved_parts, saved_ops = state["parts"], state["ops"]
    try:
        j = _js_parse_f6xx_iife_head(text, i)
        if j is None:
            raise _JSExprFail("F788 not our head")
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        sj = _js_skip_ws(stmts, 0)
        dclk, dk = _js_match_decl_kw(stmts, sj)
        if dclk is None:
            raise _JSExprFail("F788 no decl")
        ename, sj = _js_parse_ident(stmts, _js_skip_ws(stmts, dk))
        sj = _js_expect(stmts, sj, "=")
        sj = _js_skip_ws(stmts, sj)
        nk = _js_match_kw(stmts, sj, "new")
        if nk is not None:
            sj = _js_skip_ws(stmts, nk)
        cname, sj = _js_parse_ident(stmts, sj)
        if cname != "AggregateError":
            raise _JSExprFail("F788 not AggregateError")
        sj = _js_expect(stmts, sj, "(")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "[")
        elements, sj = _js_parse_string_literal_list(stmts, sj, state,
                                                     "]")
        sj = _js_skip_ws(stmts, sj)
        msg = ""
        if sj < len(stmts) and stmts[sj] == ",":
            msg, sj = _js_parse_string(stmts, _js_skip_ws(stmts, sj + 1))
        sj = _js_expect(stmts, sj, ")")
        sj = _js_expect(stmts, sj, ";")
        state["parts"] += 1
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("F788 too many parts")
        sj = _js_skip_ws(stmts, sj)
        rk = _js_match_kw(stmts, sj, "return")
        if rk is None:
            raise _JSExprFail("F788 no return")
        sj = _js_skip_ws(stmts, rk)
        terms = []
        while True:
            sj = _js_skip_ws(stmts, sj)
            if sj < len(stmts) and stmts[sj] in "'\"":
                s, sj = _js_parse_string(stmts, sj)
                terms.append(("lit", s))
            else:
                name, k = _js_parse_ident(stmts, sj)
                if name != ename:
                    raise _JSExprFail("F788 bad return term")
                k = _js_skip_ws(stmts, k)
                if k < len(stmts) and stmts[k] == ".":
                    mname, k = _js_parse_ident(stmts,
                                               _js_skip_ws(stmts, k + 1))
                elif k < len(stmts) and stmts[k] == "[":
                    mname, k = _js_parse_string(stmts,
                                                _js_skip_ws(stmts, k + 1))
                    k = _js_expect(stmts, k, "]")
                else:
                    raise _JSExprFail("F788 bad member read")
                k = _js_skip_ws(stmts, k)
                if mname == "message":
                    terms.append(("msg",))
                elif mname == "errors":
                    if k < len(stmts) and stmts[k] == "[":
                        k = _js_skip_ws(stmts, k + 1)
                        d0 = k
                        while k < len(stmts) and stmts[k] in "0123456789":
                            k += 1
                        idx = stmts[d0:k]
                        # Only canonical non-negative integer
                        # indices; anything else fails closed.
                        if (not idx or (len(idx) > 1 and idx[0] == "0")):
                            raise _JSExprFail("F788 bad index")
                        ii = int(idx)
                        if ii >= len(elements):
                            raise _JSExprFail("F788 index oob")
                        k = _js_expect(stmts, k, "]")
                        terms.append(("idx", ii))
                    elif k < len(stmts) and stmts[k] == ".":
                        jm, k = _js_parse_ident(stmts,
                                                _js_skip_ws(stmts, k + 1))
                        if jm != "join":
                            raise _JSExprFail("F788 not join")
                        k = _js_expect(stmts, k, "(")
                        k = _js_skip_ws(stmts, k)
                        if k < len(stmts) and stmts[k] == ")":
                            sep = ","
                        else:
                            sep, k = _js_parse_string(stmts, k)
                            k = _js_skip_ws(stmts, k)
                        k = _js_expect(stmts, k, ")")
                        terms.append(("join", sep))
                    else:
                        # Bare `e.errors`: Array-toString.
                        terms.append(("join", ","))
                else:
                    raise _JSExprFail("F788 not errors/message")
                sj = k
            state["parts"] += 1
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("F788 too many parts")
            sj = _js_skip_ws(stmts, sj)
            if sj < len(stmts) and stmts[sj] == "+":
                sj = sj + 1
                continue
            break
        sj = _js_expect(stmts, sj, ";")
        parts = []
        for t in terms:
            if t[0] == "lit":
                parts.append(t[1])
            elif t[0] == "msg":
                parts.append(msg)
            elif t[0] == "idx":
                parts.append(elements[t[1]])
            else:
                parts.append(t[1].join(elements))
        rval = "".join(parts)
        if len(rval) > _MAX_DECODE_BYTES:
            raise _JSExprFail("F788 concat too long")
        if _js_skip_ws(stmts, sj) != len(stmts):
            raise _JSExprFail("F788 trailing statements")
        return _js_parse_f6xx_iife_tail(text, j, depth, state, rval)
    except _JSExprFail:
        state["parts"], state["ops"] = saved_parts, saved_ops
        return None




def _js_parse_decimal_literal(text, j, what):
    """Parse a decimal integer literal at text[j] (F792).

    Returns (num, next_index); raises _JSExprFail when no digits
    are present. Never evals.
    """
    n = len(text)
    d0 = j
    while j < n and text[j] in "0123456789":
        j += 1
    if j == d0:
        raise _JSExprFail(what)
    return int(text[d0:j]), j


def _js_f792_parse_const_key(text, j):
    """Parse a constant string-literal key at text[j] (F792).

    Every item groups under the literal key (node-exact).
    Returns (("const", key), next_index). Never evals.
    """
    key, q = _js_parse_string(text, j)
    if not isinstance(key, str) or isinstance(key, _JSNumStr):
        raise _JSExprFail("F792 const key not plain")
    return ("const", key), q


def _js_f792_parse_callback(text, j, state):
    """Parse a groupBy callback at text[j] (F792).

    `function(IDENT){return IDENT;}` /
    `function(IDENT){return IDENT[NUM];}` and the arrow twins
    `(IDENT)=>IDENT` / `(IDENT)=>IDENT[NUM]` / `IDENT=>IDENT` /
    `IDENT=>IDENT[NUM]` (ws-tolerant). The returned ident must be
    the parameter. A string-literal key (`return 'K';` / `=>'K'`)
    groups every item under the constant K (node-exact).
    Returns (("ident",) / ("index", num) / ("const", key),
    next_index). Anything else (extra params, other bodies,
    non-literal index) fails closed. Never evals.
    """
    n = len(text)
    fk = _js_match_kw(text, j, "function")
    if fk is not None:
        q = _js_skip_ws(text, fk)
        q = _js_expect(text, q, "(")
        q = _js_skip_ws(text, q)
        param, q = _js_parse_ident(text, q)
        q = _js_skip_ws(text, q)
        q = _js_expect(text, q, ")")
        q = _js_skip_ws(text, q)
        q = _js_expect(text, q, "{")
        q = _js_skip_ws(text, q)
        rk = _js_match_kw(text, q, "return")
        if rk is None:
            raise _JSExprFail("F792 callback no return")
        q = _js_skip_ws(text, rk)
        if q < n and text[q] in "'\"":
            # Constant string-literal key: every item groups under K.
            form, q = _js_f792_parse_const_key(text, q)
            q = _js_skip_ws(text, q)
        else:
            name, q = _js_parse_ident(text, q)
            if name != param:
                raise _JSExprFail("F792 callback param mismatch")
            form, q = _js_f792_parse_key_subscript(text, q)
            q = _js_skip_ws(text, q)
        q = _js_expect(text, q, ";")
        q = _js_skip_ws(text, q)
        q = _js_expect(text, q, "}")
        _js_f792_charge(state)
        return form, q
    # Arrow: `(IDENT)=>` / `IDENT=>`, ws-tolerant.
    q = _js_skip_ws(text, j)
    if q < n and text[q] == "(":
        q = _js_skip_ws(text, q + 1)
        param, q = _js_parse_ident(text, q)
        q = _js_skip_ws(text, q)
        q = _js_expect(text, q, ")")
    else:
        param, q = _js_parse_ident(text, q)
    q = _js_skip_ws(text, q)
    if not text.startswith("=>", q):
        raise _JSExprFail("F792 callback not arrow")
    q = _js_skip_ws(text, q + 2)
    if q < n and text[q] in "'\"":
        # Constant string-literal key: every item groups under K.
        form, q = _js_f792_parse_const_key(text, q)
    else:
        name, q = _js_parse_ident(text, q)
        if name != param:
            raise _JSExprFail("F792 callback param mismatch")
        form, q = _js_f792_parse_key_subscript(text, q)
    _js_f792_charge(state)
    return form, q


def _js_f792_parse_key_subscript(text, j):
    """Parse the optional key subscript at text[j] (F792).

    The caller has already consumed and validated the callback's
    parameter ident; this parses the optional `[NUM]` subscript
    (`IDENT[NUM]`), or nothing for the bare-ident form. Returns
    (("ident",) / ("index", num), next_index). Never evals.
    """
    n = len(text)
    q = _js_skip_ws(text, j)
    if q < n and text[q] == "[":
        q = _js_skip_ws(text, q + 1)
        num, q = _js_parse_decimal_literal(
            text, q, "F792 key index not literal")
        q = _js_skip_ws(text, q)
        q = _js_expect(text, q, "]")
        return ("index", num), q
    return ("ident",), j


def _js_f792_charge(state):
    """Charge one F452 part and fail closed past the budget (F792)."""
    state["parts"] += 1  # the grouping step is obfuscation-shaped
    if state["parts"] > _JS_EXPR_MAX_PARTS:
        raise _JSExprFail("F792 too many parts")


def _js_parse_f792_groupby_iife(text, i, depth, state):
    """Parse `(function(){var M=(Map|Object).groupBy([...],CB);return ADD;})()` (F792).

    F792 (LOW, filed 2026-10-09 by wave-384 attack round 52): the
    decoder has no groupBy production, so the ES2024
    `Map.groupBy`/`Object.groupBy` builtins group fragments
    node-exactly while the decoder produces zero variants:
      `(function(){var m=Map.groupBy(['f1','f2'],function(x){return x[0];});`
      `return m.get('x')[0]+m.get('4')[0];})()`
      `(function(){var o=Object.groupBy(['f1','f2'],function(x){return x[0];});`
      `return o.x[0]+o['4'][0];})()`
    Node-exact (v24.20.0) on the modeled subset: items are string
    literals; the callback is `function(IDENT){return IDENT;}` /
    `function(IDENT){return IDENT[NUM];}` / the constant-key
    `function(IDENT){return 'K';}` or the arrow twins (the
    returned ident is the parameter); keys are the callback
    results in order (insertion-ordered groups, engine-exact);
    `Map` reads are `M.get('K')[NUM]`, `Object` reads are
    `M.K[NUM]` / `M['K'][NUM]` (cross-kind accessors throw in the
    engine -- fail closed); a missing group key throws in the
    engine (reading `[NUM]` off `undefined`); an out-of-range
    index yields `undefined` (non-string) -- both fail closed in
    the string-only discipline.

    Grammar (all fail closed -- rejected, never mis-decoded):
    - head: plain `(function(){` (shared F654 head); no params,
      no name, no async.
    - exactly one statement: `var|let|const M=(Map|Object).groupBy(`
      `[LIT(,LIT)*], CB);` (exactly two call args).
    - return: `ADD;` -- a `+`-additive of string literals and
      group reads (at least one group read, else the grouping is
      dead and an earlier route owns the shape).
    - exactly `()` invocation; no trailing statements.

    Tried after F757: every accepted shape carries a
    `(Map|Object).groupBy(` statement head, which no earlier
    route accepts (red-first verified: 2 BREAK on the open tree).
    Only previously fail-closed inputs are newly decoded, so no
    previously-decoded input changes behavior. None falls through
    to the parenthesized-additive path. F452 parts charged per
    array item, per callback, and per read term; results bounded
    by _MAX_DECODE_BYTES. Returns (value, next_index), or None
    when text[i] is not this shape. Never evals.
    """
    n = len(text)
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    try:
        brace = _js_parse_f654_sync_iife_head(text, i)
        if brace is None:
            return None
        inner_start, inner_end, j = _js_span_braced(text, brace)
        sj = _js_skip_ws(text, inner_start)
        dkw, m = _js_match_decl_kw(text, sj)
        if dkw is None:
            return None
        q = _js_skip_ws(text, m)
        mname, q = _js_parse_ident(text, q)
        q = _js_skip_ws(text, q)
        q = _js_expect(text, q, "=")
        q = _js_skip_ws(text, q)
        is_map = None
        for holder in ("Map", "Object"):
            hk = _js_match_kw(text, q, holder)
            if hk is None:
                continue
            q2 = _js_skip_ws(text, hk)
            if q2 >= n or text[q2] != ".":
                continue
            q3 = _js_skip_ws(text, q2 + 1)
            gk = _js_match_kw(text, q3, "groupBy")
            if gk is None:
                continue
            is_map = (holder == "Map")
            q = _js_skip_ws(text, gk)
            break
        if is_map is None:
            return None
        q = _js_expect(text, q, "(")
        q = _js_skip_ws(text, q)
        q = _js_expect(text, q, "[")
        items, q = _js_parse_string_literal_list(text, q, state, "]")
        q = _js_skip_ws(text, q)
        q = _js_expect(text, q, ",")
        cb, q = _js_f792_parse_callback(text, _js_skip_ws(text, q),
                                        state)
        q = _js_skip_ws(text, q)
        q = _js_expect(text, q, ")")
        q = _js_skip_ws(text, q)
        q = _js_expect(text, q, ";")
        # Group node-exactly (insertion order, engine-exact).
        groups = {}
        for item in items:
            if not isinstance(item, str) or isinstance(item, _JSNumStr):
                raise _JSExprFail("F792 item not a plain string")
            if cb[0] == "ident":
                key = item
            elif cb[0] == "const":
                key = cb[1]
            else:
                num = cb[1]
                if num >= len(item):
                    # Engine groups under `undefined`; outside the
                    # string-only discipline -- fail closed.
                    raise _JSExprFail("F792 key index out of range")
                key = item[num]
            if key in groups:
                groups[key].append(item)
            else:
                groups[key] = [item]
            _js_f792_charge(state)
        sj = _js_skip_ws(text, q)
        rk = _js_match_kw(text, sj, "return")
        if rk is None:
            raise _JSExprFail("F792 no return")
        q = _js_skip_ws(text, rk)
        val, saw_read, q = _js_f792_parse_return_additive(
            text, q, mname, is_map, groups, state)
        if not saw_read:
            raise _JSExprFail("F792 no group read")
        if len(val) > _MAX_DECODE_BYTES:
            raise _JSExprFail("F792 concat too long")
        q = _js_skip_ws(text, q)
        q = _js_expect(text, q, ";")
        q = _js_skip_ws(text, q)
        if q != inner_end:
            raise _JSExprFail("F792 trailing statements")
        # Invocation: exactly `()`.
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return val, j
    except _JSExprFail:
        return None


# ---------------------------------------------------------------------------
# F799: subclassed builtin reads (class S extends String{} / class A extends Array{})
# ---------------------------------------------------------------------------

def _js_parse_f799_class_decl(stmts, j):
    """Parse `class NAME extends String|Array{}` at stmts[j] (F799).

    The subclass declaration: exactly `class`, an identifier, the
    `extends` keyword, the `String` or `Array` identifier, and an
    EMPTY class body (whitespace only -- methods, constructors,
    fields, statics, or computed names fail closed; the engine
    would give them semantics the static model cannot see, e.g. an
    overridden valueOf/toString changes the read result
    node-verifiably). Returns (name, base, next_index). Raises
    _JSExprFail. Never evals.
    """
    n = len(stmts)
    k = _js_match_kw(stmts, j, "class")
    if k is None:
        raise _JSExprFail("F799 not a class declaration")
    k = _js_skip_ws(stmts, k)
    name, k = _js_parse_ident(stmts, k)
    if name == "arguments":
        raise _JSExprFail("F799 class named arguments")
    k = _js_skip_ws(stmts, k)
    e = _js_match_kw(stmts, k, "extends")
    if e is None:
        raise _JSExprFail("F799 class without extends")
    e = _js_skip_ws(stmts, e)
    base, e = _js_parse_ident(stmts, e)
    if base not in ("String", "Array"):
        raise _JSExprFail("F799 superclass not String/Array")
    if name == base:
        # `class String extends String{}`: the heritage position is
        # evaluated with the subclass name in TDZ -- node throws
        # ReferenceError. Refuse rather than emit a value for
        # throwing code.
        raise _JSExprFail("F799 subclass shadows its heritage")
    e = _js_skip_ws(stmts, e)
    if e >= n or stmts[e] != "{":
        raise _JSExprFail("F799 class without body")
    e = _js_skip_ws(stmts, e + 1)
    if e >= n or stmts[e] != "}":
        raise _JSExprFail("F799 non-empty class body")
    return name, base, e + 1


def _js_f799_parse_new_args(stmts, q, base, depth, state):
    """Parse the `(ARGS)` of `new S(ARGS)` at stmts[q] (F799).

    String subclass: zero or more string literals; the instance
    wraps the FIRST literal (extras ignored -- node-exact:
    `new S('a','b').valueOf()` is 'a'; `new S()` is ''). A
    non-string-literal arg fails closed.
    Array subclass: string literals become elements; a SINGLE
    non-negative integer literal means holes of that length
    (F443 holes-as-"" contract -- joins compute arithmetically,
    never materialized); `new A('x')` is the single-element ['x']
    (node-exact -- a lone string arg is an element, not a length).
    Anything else fails closed. Returns (kind, data, next_index):
    kind "str" -> data is the primitive string; kind "arr" -> data
    is the element list or the hole count (int). Raises
    _JSExprFail. Never evals.
    """
    n = len(stmts)
    q = _js_skip_ws(stmts, q)
    q = _js_expect(stmts, q, "(")
    args = []
    q = _js_skip_ws(stmts, q)
    if q >= n:
        raise _JSExprFail("F799 unterminated new args")
    if stmts[q] != ")":
        while True:
            q = _js_skip_ws(stmts, q)
            if q < n and stmts[q] in "'\"":
                lit, q = _js_parse_string(stmts, q)
                args.append(("s", lit))
            else:
                num, q = _js_parse_number(stmts, q)
                args.append(("n", num))
            state["parts"] += 1  # F452: charge per argument
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
            q = _js_skip_ws(stmts, q)
            if q < n and stmts[q] == ",":
                q = _js_skip_ws(stmts, q + 1)
                continue
            break
    q = _js_skip_ws(stmts, q)
    q = _js_expect(stmts, q, ")")
    if base == "String":
        for kind, _v in args:
            if kind != "s":
                raise _JSExprFail("F799 String arg not a string")
        return "str", (args[0][1] if args else ""), q
    if len(args) == 1 and args[0][0] == "n":
        return "arr", args[0][1], q
    elems = []
    for kind, v in args:
        if kind != "s":
            raise _JSExprFail("F799 Array arg not a string")
        elems.append(v)
    return "arr", elems, q


def _js_f799_parse_read(stmts, q, xname, kind, data, depth, state):
    """Parse the `x.METHOD(...)(+'LIT')*;` return at stmts[q] (F799).

    kind "str": `.valueOf()` / `.toString()` (dot or
    bracket-string twin), zero args -- the wrapped primitive.
    kind "arr": `.join('SEP')` (one string-literal arg) or
    `.toString()` (dot or bracket twin) -- the joined elements
    (holes join arithmetically, bounded by _MAX_DECODE_BYTES).
    Array `valueOf` returns the object (out of the string-ADD
    model) and String has no `join` (the engine throws) -- both
    fail closed. The additive tail is string literals only (F746
    discipline). Returns (value, next_index). Raises _JSExprFail.
    Never evals.
    """
    n = len(stmts)
    q = _js_skip_ws(stmts, q)
    rname, q = _js_parse_ident(stmts, q)
    if rname != xname:
        raise _JSExprFail("F799 return not the instance")
    q = _js_skip_ws(stmts, q)
    if q < n and stmts[q] == ".":
        q = _js_skip_ws(stmts, q + 1)
        mname, q = _js_parse_ident(stmts, q)
    elif q < n and stmts[q] == "[":
        q = _js_skip_ws(stmts, q + 1)
        if q >= n or stmts[q] not in "'\"":
            raise _JSExprFail("F799 member not a string")
        mname, q = _js_parse_string(stmts, q)
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, "]")
    else:
        raise _JSExprFail("F799 return not a member read")
    q = _js_skip_ws(stmts, q)
    q = _js_expect(stmts, q, "(")
    q = _js_skip_ws(stmts, q)
    if kind == "str":
        if mname not in ("valueOf", "toString"):
            raise _JSExprFail("F799 String method not modeled")
        q = _js_expect(stmts, q, ")")
        val = data
    else:
        if mname == "join":
            if q >= n or stmts[q] not in "'\"":
                raise _JSExprFail("F799 join sep not a string")
            sep, q = _js_parse_string(stmts, q)
            q = _js_skip_ws(stmts, q)
            q = _js_expect(stmts, q, ")")
            if isinstance(data, int):
                if data == 0:
                    val = ""
                else:
                    if len(sep) * (data - 1) > _MAX_DECODE_BYTES:
                        raise _JSExprFail("F799 join too long")
                    val = sep * (data - 1)
            else:
                val = sep.join(data)
                if len(val) > _MAX_DECODE_BYTES:
                    raise _JSExprFail("F799 join too long")
        elif mname == "toString":
            q = _js_expect(stmts, q, ")")
            if isinstance(data, int):
                if data and data - 1 > _MAX_DECODE_BYTES:
                    raise _JSExprFail("F799 toString too long")
                val = "," * (data - 1) if data else ""
                if len(val) > _MAX_DECODE_BYTES:
                    raise _JSExprFail("F799 join too long")
            else:
                val = ",".join(data)
        else:
            raise _JSExprFail("F799 Array method not modeled")
    state["ops"] += 1  # the read is obfuscation-shaped
    while True:
        t = _js_skip_ws(stmts, q)
        if t >= n or stmts[t] != "+":
            break
        t = _js_skip_ws(stmts, t + 1)
        if t >= n or stmts[t] not in "'\"":
            raise _JSExprFail("F799 tail not a literal")
        _tail, t = _js_parse_string(stmts, t)
        if len(val) + len(_tail) > _MAX_DECODE_BYTES:
            raise _JSExprFail("F799 concat too long")
        val = val + _tail
        state["parts"] += 1
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        state["ops"] += 1
        q = t
    return val, q


def _js_parse_f799_subclass_builtin_iife(text, i, depth, state):
    """Parse `(function(){class S extends String|Array{}var|let|const x=new S(ARGS);return READ(+LIT)*;})()` (F799).

    F799 (LOW, wave-385 attack round 53): the decoder models
    subclassed Map construction (F746, CLOSED) but has no
    subclass production for String/Array -- `class S extends
    String{}` / `class A extends Array{}` instances resolve
    `valueOf()`/`toString()`/`join()` node-exactly while the
    decoder produces zero variants.

    Node-exact desugar (v24.20.0): the class declaration binds S
    as a String/Array subclass (empty body only -- the default
    derived constructor forwards to super); `new S(ARGS)` builds
    the wrapped primitive / element list with constructor
    semantics (`new S('a','b')` wraps 'a'; `new A('x')` is ['x'];
    `new A(3)` is 3 holes); the return reads the instance through
    the modeled methods and an optional literal additive tail.

    Disjointness: tried after F792. Every accepted shape carries
    a leading `class NAME extends String|Array{}` declaration
    with an empty body, which no earlier route accepts (F783
    requires the superclass to be a previously-declared class,
    so it fails closed on `extends String`; red-first verified:
    2 BREAK on the open tree). None falls through to the
    parenthesized-additive path.

    Bounds (all fail closed -- rejected, never mis-decoded): a
    non-empty class body, a non-String/Array superclass, a
    non-literal constructor arg (String) / non-string-literal arg
    (Array, except the single-integer holes form), a shadowed
    subclass or instance name, an unmodeled method (`join` on a
    String -- the engine throws; `valueOf` on an Array -- returns
    the object), a non-literal join separator or tail, extra
    statements, call args on the IIFE. Method-shorthand and
    multi-statement bodies are documented residuals.
    Returns (value, next_index), or None when the head does not
    match or a guard fails. Never evals.
    """
    j = _js_parse_f6xx_iife_head(text, i)
    if j is None:
        return None
    try:
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        n = len(stmts)
        sj = _js_skip_ws(stmts, 0)
        # `class S extends String|Array{}`
        subname, base, sj = _js_parse_f799_class_decl(stmts, sj)
        sj = _js_skip_ws(stmts, sj)
        # `var|let|const x = new S(ARGS);`
        dkw, q = _js_match_decl_kw(stmts, sj)
        if dkw is None:
            raise _JSExprFail("F799 decl not var/let/const")
        q = _js_skip_ws(stmts, q)
        xname, q = _js_parse_ident(stmts, q)
        if xname in (subname, "arguments"):
            raise _JSExprFail("F799 instance shadows subclass")
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, "=")
        q = _js_skip_ws(stmts, q)
        nk = _js_match_kw(stmts, q, "new")
        if nk is None:
            raise _JSExprFail("F799 not a new-expression")
        nk = _js_skip_ws(stmts, nk)
        cname, nk = _js_parse_ident(stmts, nk)
        if cname != subname:
            raise _JSExprFail("F799 not the subclass ctor")
        kind, data, nk = _js_f799_parse_new_args(stmts, nk, base,
                                                depth, state)
        nk = _js_skip_ws(stmts, nk)
        nk = _js_expect(stmts, nk, ";")
        state["parts"] += 1  # the construction is shaped
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        # `return READ(+ 'LIT')*;`
        rk = _js_match_kw(stmts, _js_skip_ws(stmts, nk), "return")
        if rk is None:
            raise _JSExprFail("F799 body not return")
        q = _js_skip_ws(stmts, rk)
        val, q = _js_f799_parse_read(stmts, q, xname, kind, data,
                                    depth, state)
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, ";")
        if _js_skip_ws(stmts, q) != n:
            raise _JSExprFail("F799 trailing statements")
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("too deep")
        return _js_parse_f6xx_iife_tail(text, j, depth, state, val)
    except _JSExprFail:
        return None


# ---------------------------------------------------------------------------
# F800: Proxy get-trap residuals (constant-return function get bodies; Proxy.revocable)
# ---------------------------------------------------------------------------

def _js_f800_parse_const_get_handler(stmts, q, depth, state):
    """Parse `{get:function(P...){return 'LIT';}}`, `{get:(P...)=>'LIT'}`, or
    `{get(P...){return 'LIT';}}` at stmts[q] (F800/F909).

    The constant-return get trap: the engine invokes the trap
    with (target, key, receiver) and returns its result, so a
    body that returns a string literal makes EVERY property read
    on the proxy resolve to that literal node-exactly (v24.20.0).
    The property form admits the function expression (optional
    name) and the arrow; F909 adds the method-shorthand form
    `get(){return 'LIT';}`. The param list admits 0, 1, or 2
    simple identifiers -- a constant-return body ignores its
    params, so arity is engine-irrelevant (node v24.20.0).
    The body must be exactly a single string-literal return
    (function/shorthand) or a string-literal arrow body. Extra
    handler keys, non-constant bodies, 3+ params, rest params, or
    a named trap all fail closed (documented boundary). Returns
    (literal, next_index). Raises _JSExprFail. Never evals.
    """
    n = len(stmts)
    q = _js_skip_ws(stmts, q)
    q = _js_expect(stmts, q, "{")
    q = _js_skip_ws(stmts, q)
    gname, q = _js_parse_ident(stmts, q)
    if gname != "get":
        raise _JSExprFail("F800 handler not a get trap")
    q = _js_skip_ws(stmts, q)

    def _parse_params(k):
        # Parse `(P,)*` -- 0, 1, or 2 simple identifiers (F909).
        k = _js_expect(stmts, k, "(")
        k = _js_skip_ws(stmts, k)
        _count = 0
        while k < n and stmts[k] != ")":
            if _count >= 2:
                raise _JSExprFail("F800 too many params")
            _p, k = _js_parse_ident(stmts, k)
            _count += 1
            k = _js_skip_ws(stmts, k)
            if k < n and stmts[k] == ",":
                k = _js_skip_ws(stmts, k + 1)
                if k < n and stmts[k] == ")":
                    raise _JSExprFail("F800 trailing comma")
        k = _js_expect(stmts, k, ")")
        return k

    def _parse_return_lit_body(k):
        # Parse `{return 'LIT';}`. Returns (literal, next_index).
        k = _js_skip_ws(stmts, k)
        k = _js_expect(stmts, k, "{")
        k = _js_skip_ws(stmts, k)
        rk = _js_match_kw(stmts, k, "return")
        if rk is None:
            raise _JSExprFail("F800 get body not a return")
        k = _js_skip_ws(stmts, rk)
        if k >= n or stmts[k] not in "'\"":
            raise _JSExprFail("F800 get return not a string")
        lit, k = _js_parse_string(stmts, k)
        k = _js_skip_ws(stmts, k)
        k = _js_expect(stmts, k, ";")
        k = _js_skip_ws(stmts, k)
        k = _js_expect(stmts, k, "}")
        return lit, k

    if q < n and stmts[q] == "(":
        # F909: method-shorthand form `get(P...){return 'LIT';}`.
        q = _parse_params(q)
        lit, q = _parse_return_lit_body(q)
    else:
        q = _js_expect(stmts, q, ":")
        q = _js_skip_ws(stmts, q)
        fk = _js_match_kw(stmts, q, "function")
        if fk is not None:
            q = _js_skip_ws(stmts, fk)
            if q < n and (stmts[q].isalpha() or stmts[q] in "_$"):
                try:
                    _fname, q2 = _js_parse_ident(stmts, q)
                    q2 = _js_skip_ws(stmts, q2)
                    if q2 < n and stmts[q2] == "(":
                        q = q2
                except _JSExprFail:
                    pass
            q = _parse_params(q)
            lit, q = _parse_return_lit_body(q)
        else:
            q = _parse_params(q)
            q = _js_skip_ws(stmts, q)
            if q + 1 >= n or stmts[q] != "=" or stmts[q + 1] != ">":
                raise _JSExprFail("F800 not an arrow get trap")
            q = _js_skip_ws(stmts, q + 2)
            if q >= n or stmts[q] not in "'\"":
                raise _JSExprFail("F800 arrow body not a string")
            lit, q = _js_parse_string(stmts, q)
    q = _js_skip_ws(stmts, q)
    q = _js_expect(stmts, q, "}")
    state["parts"] += 1  # the trap is shaped
    if state["parts"] > _JS_EXPR_MAX_PARTS:
        raise _JSExprFail("too many parts")
    return lit, q


def _js_f800_parse_member(stmts, q):
    """Parse `.NAME` or `['NAME']` at stmts[q] (F800). Returns (name, next_index)."""
    n = len(stmts)
    q = _js_skip_ws(stmts, q)
    if q < n and stmts[q] == ".":
        q = _js_skip_ws(stmts, q + 1)
        return _js_parse_ident(stmts, q)
    if q < n and stmts[q] == "[":
        q = _js_skip_ws(stmts, q + 1)
        if q >= n or stmts[q] not in "'\"":
            raise _JSExprFail("F800 member not a string")
        name, q = _js_parse_string(stmts, q)
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, "]")
        return name, q
    raise _JSExprFail("F800 not a member read")


def _js_f800_parse_literal_tail(stmts, q, val, depth, state):
    """Parse `(+'LIT')*` at stmts[q], appending to val (F800, F746 discipline)."""
    n = len(stmts)
    while True:
        t = _js_skip_ws(stmts, q)
        if t >= n or stmts[t] != "+":
            break
        t = _js_skip_ws(stmts, t + 1)
        if t >= n or stmts[t] not in "'\"":
            raise _JSExprFail("F800 tail not a literal")
        _tail, t = _js_parse_string(stmts, t)
        if len(val) + len(_tail) > _MAX_DECODE_BYTES:
            raise _JSExprFail("F800 concat too long")
        val = val + _tail
        state["parts"] += 1
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        state["ops"] += 1
        q = t
    return val, q


def _js_parse_f800_proxy_residual_iife(text, i, depth, state):
    """Parse the F800 Proxy get-trap residual twins (F800).

    F800 (LOW, wave-385 attack round 53): F642 (CLOSED, wave-376
    lane 3) models get traps, but var-bound proxies with
    function-form get bodies and Proxy.revocable miss while node
    resolves them exactly:
      `(function(){var p=new Proxy({},{get:function(t,k){return 'f1';}});return p.anything+'f2';})()`
      `(function(){var r=Proxy.revocable({k:'f1'},{});return r.proxy.k+'f2';})()`
    (Round-52's Proxy.revocable BLOCK note was incorrect for these
    shapes; verified miss.)

    Node-exact desugar (v24.20.0). Twin 1: the constant-return
    get trap makes every property read on the proxy resolve to
    the returned literal (the target literal is parsed and
    discarded -- the trap never consults it). Twin 2:
    `Proxy.revocable(TARGET, {})` returns `{proxy, revoke}`;
    with the empty handler every trap forwards to the target
    (F587 discipline), so `r.proxy.k` reads the target's data
    property node-exactly.

    Disjointness: tried after F799. Twin 1 requires a `var
    p=new Proxy(` head with a constant-return get handler --
    F535/F587 fail closed on the handler (non-passthrough,
    non-empty) and every earlier route requires its own binding
    family (red-first verified: 2 BREAK on the open tree). Twin 2
    requires the `Proxy.revocable(` head, which no earlier route
    accepts. None falls through to the parenthesized-additive
    path.

    Bounds (all fail closed -- rejected, never mis-decoded): a
    non-constant get body, 3+ params, rest params, a trailing
    comma, extra handler keys, a non-empty revocable handler, a non-string target property, a
    `revoke()` call in the fragment (the engine throws -- the
    revoked read is unmodeled), a non-literal tail, extra
    call args on the IIFE. F909 (wave-388 lane 5): the constant-return
    handler also admits 0-param, 1-param, and method-shorthand
    forms -- arity is engine-irrelevant for constant returns.
    Returns (value, next_index), or None when the head does not
    match or a guard fails. Never evals.
    """
    j = _js_parse_f6xx_iife_head(text, i)
    if j is None:
        return None
    try:
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        n = len(stmts)
        sj = _js_skip_ws(stmts, 0)
        dkw, q = _js_match_decl_kw(stmts, sj)
        if dkw is None:
            raise _JSExprFail("F800 decl not var/let/const")
        q = _js_skip_ws(stmts, q)
        pname, q = _js_parse_ident(stmts, q)
        if pname == "arguments":
            raise _JSExprFail("F800 proxy named arguments")
        if pname == "Proxy":
            # `var Proxy=new Proxy(...)` / `var
            # Proxy=Proxy.revocable(...)`: the binding shadows the
            # global, so the RHS constructor reference is the
            # hoisted undefined var -- node throws TypeError.
            # Refuse rather than emit a value for throwing code.
            raise _JSExprFail("F800 shadows global Proxy")
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, "=")
        q = _js_skip_ws(stmts, q)
        nk = _js_match_kw(stmts, q, "new")
        if nk is not None:
            # Twin 1: `var p=new Proxy(TARGET,{get:...});`
            nk = _js_skip_ws(stmts, nk)
            cname, nk = _js_parse_ident(stmts, nk)
            if cname != "Proxy":
                raise _JSExprFail("F800 not a Proxy construction")
            nk = _js_skip_ws(stmts, nk)
            nk = _js_expect(stmts, nk, "(")
            nk = _js_skip_ws(stmts, nk)
            _tprops, nk = _js_parse_f535_object(stmts, nk, depth,
                                               state)
            nk = _js_skip_ws(stmts, nk)
            nk = _js_expect(stmts, nk, ",")
            const_lit, nk = _js_f800_parse_const_get_handler(
                stmts, nk, depth, state)
            nk = _js_skip_ws(stmts, nk)
            nk = _js_expect(stmts, nk, ")")
            nk = _js_skip_ws(stmts, nk)
            nk = _js_expect(stmts, nk, ";")
            state["parts"] += 1  # the construction is shaped
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
            rk = _js_match_kw(stmts, _js_skip_ws(stmts, nk),
                              "return")
            if rk is None:
                raise _JSExprFail("F800 body not return")
            rq = _js_skip_ws(stmts, rk)
            rname, rq = _js_parse_ident(stmts, rq)
            if rname != pname:
                raise _JSExprFail("F800 return not the proxy")
            _mname, rq = _js_f800_parse_member(stmts, rq)
            val = const_lit
            state["ops"] += 1  # the read is obfuscation-shaped
            val, rq = _js_f800_parse_literal_tail(stmts, rq, val,
                                                 depth, state)
            rq = _js_skip_ws(stmts, rq)
            rq = _js_expect(stmts, rq, ";")
        else:
            # Twin 2: `var r=Proxy.revocable(TARGET,{});`
            if not stmts.startswith("Proxy", q) or \
                    (q + 5 < n and stmts[q + 5] in _JS_IDENT_CONT):
                raise _JSExprFail("F800 not Proxy.revocable")
            q = _js_skip_ws(stmts, q + 5)
            q = _js_expect(stmts, q, ".")
            q = _js_skip_ws(stmts, q)
            mname, q = _js_parse_ident(stmts, q)
            if mname != "revocable":
                raise _JSExprFail("F800 not revocable")
            q = _js_skip_ws(stmts, q)
            q = _js_expect(stmts, q, "(")
            q = _js_skip_ws(stmts, q)
            tprops, q = _js_parse_f535_object(stmts, q, depth,
                                             state)
            q = _js_skip_ws(stmts, q)
            q = _js_expect(stmts, q, ",")
            q = _js_skip_ws(stmts, q)
            q = _js_expect(stmts, q, "{")
            q = _js_skip_ws(stmts, q)
            q = _js_expect(stmts, q, "}")
            q = _js_skip_ws(stmts, q)
            q = _js_expect(stmts, q, ")")
            q = _js_skip_ws(stmts, q)
            q = _js_expect(stmts, q, ";")
            state["parts"] += 1  # the construction is shaped
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
            rk = _js_match_kw(stmts, _js_skip_ws(stmts, q),
                              "return")
            if rk is None:
                raise _JSExprFail("F800 body not return")
            rq = _js_skip_ws(stmts, rk)
            rname, rq = _js_parse_ident(stmts, rq)
            if rname != pname:
                raise _JSExprFail("F800 return not the revocable")
            pm, rq = _js_f800_parse_member(stmts, rq)
            if pm != "proxy":
                raise _JSExprFail("F800 not the proxy member")
            km, rq = _js_f800_parse_member(stmts, rq)
            kval = tprops.get(km)
            if not isinstance(kval, str) or \
                    isinstance(kval, _JSNumStr):
                raise _JSExprFail("F800 key not a plain string")
            val = kval
            state["ops"] += 1  # the read is obfuscation-shaped
            val, rq = _js_f800_parse_literal_tail(stmts, rq, val,
                                                 depth, state)
            rq = _js_skip_ws(stmts, rq)
            rq = _js_expect(stmts, rq, ";")
        if _js_skip_ws(stmts, rq) != n:
            raise _JSExprFail("F800 trailing statements")
        if depth >= _JS_EXPR_MAX_DEPTH:
            raise _JSExprFail("too deep")
        return _js_parse_f6xx_iife_tail(text, j, depth, state, val)
    except _JSExprFail:
        return None

# ---------------------------------------------------------------------------
# F849: throw/catch value flows (primitive throws, {message} throws)
# ---------------------------------------------------------------------------

def _js_f849_parse_throw_operand(stmts, j, depth, state):
    """Parse the `throw` operand at stmts[j] (F849).

    Returns (kind, value, next_index): kind 'str' for a plain string
    literal (`throw 'LIT'`), kind 'msg' for an object literal with
    exactly one plain-string `message` property
    (`throw {message:'LIT'}` / `throw {'message':'LIT'}`). `new
    Error(...)` / `new TypeError(...)` constructions (F750) and the
    cause-options form (F787) fail closed here; idents, numbers, and
    multi-property objects fail closed. Never evals.
    """
    n = len(stmts)
    j = _js_skip_ws(stmts, j)
    if j < n and stmts[j] in "'\"":
        lit, j = _js_parse_string(stmts, j)
        if not isinstance(lit, str) or isinstance(lit, _JSNumStr):
            raise _JSExprFail("F849 throw lit not plain")
        state["parts"] += 1
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        return "str", lit, j
    if j < n and stmts[j] == "{":
        props, j = _js_parse_f535_object(stmts, j, depth, state)
        keys = [k for k in props.keys() if isinstance(k, str)]
        if len(props) != 1 or len(keys) != 1 or keys[0] != "message":
            raise _JSExprFail("F849 throw obj not {message}")
        lit = props["message"]
        if not isinstance(lit, str) or isinstance(lit, _JSNumStr):
            raise _JSExprFail("F849 throw message not plain")
        return "msg", lit, j
    raise _JSExprFail("F849 throw operand not modeled")


def _js_f849_parse_copy_decls(stmts, j, cname, aliases, state):
    """Parse `(var|let|const NAME=(CNAME|ALIAS);)*` at stmts[j] (F902).

    The engine copies the thrown string into each new binding
    (node-exact, v24.20.0); the return additive then resolves
    each alias to the thrown value. Only the string-throw kind
    admits copies (the caller gates on kind == "str"): for the
    `{message:'LIT'}` twin a copy would alias the thrown object,
    whose bare read stringifies to `[object Object]` in the
    engine -- outside the string-only discipline. A `const` copy
    reads identically (no reassignment is reachable before the
    return). Each name must be fresh (not `arguments`, not the
    catch param, no duplicates); the RHS must be the catch param
    or a previously-declared alias (chained copies are
    node-exact). Anything else -- reassignment, a
    multi-declarator, a non-copy initializer -- fails closed
    (the `return` must immediately follow the copies). Returns
    the index just past the last `;`. Never evals.
    """
    n = len(stmts)
    while True:
        dk, m = _js_match_decl_kw(stmts, j)
        if dk is None:
            return j
        q = _js_skip_ws(stmts, m)
        name, q = _js_parse_ident(stmts, q)
        if name == "arguments" or name == cname or name in aliases:
            raise _JSExprFail("F902 bad copy name")
        q = _js_skip_ws(stmts, q)
        if q >= n or stmts[q] != "=" or stmts.startswith(("==", "=>"), q):
            raise _JSExprFail("F902 copy not an assignment")
        q = _js_skip_ws(stmts, q + 1)
        sname, q = _js_parse_ident(stmts, q)
        if sname != cname and sname not in aliases:
            raise _JSExprFail("F902 copy source not the thrown value")
        q = _js_skip_ws(stmts, q)
        if q < n and stmts[q] == ",":
            raise _JSExprFail("F902 multi-declarator")
        q = _js_expect(stmts, q, ";")
        aliases.add(name)
        _js_f672_charge(state)
        j = q


def _js_f849_parse_catch_additive(stmts, j, cname, kind, thrown, state,
                                 aliases=()):
    """Parse `TERM (+ TERM)*` at stmts[j] (F849).

    TERM is a plain string literal, the bare catch param (only when
    the throwable is a string literal -- the engine binds the param
    to the thrown value), a copy alias declared by
    `_js_f849_parse_copy_decls` (F902 -- resolves to the thrown
    string exactly like the bare param), or `C.message` /
    `C['message']` / `C["message"]` (only when the throwable is
    `{message:'LIT'}`).
    Cross-combos fail closed: `'LIT'.message` is `undefined` and a
    thrown object stringifies to `[object Object]` -- both outside
    the string-only discipline. Returns (value, next_index) with
    the value bounded by _MAX_DECODE_BYTES. Never evals.
    """
    n = len(stmts)
    out = []
    while True:
        j = _js_skip_ws(stmts, j)
        if j >= n:
            raise _JSExprFail("F849 term overrun")
        if stmts[j] in "'\"":
            lit, j = _js_parse_string(stmts, j)
            if not isinstance(lit, str) or isinstance(lit, _JSNumStr):
                raise _JSExprFail("F849 term not plain")
            out.append(lit)
        elif stmts[j] in _JS_IDENT_START:
            name, j = _js_parse_ident(stmts, j)
            if name != cname and name not in aliases:
                raise _JSExprFail("F849 term not the catch param")
            q = _js_skip_ws(stmts, j)
            if q < n and stmts[q] == ".":
                mname, q = _js_parse_ident(stmts,
                                           _js_skip_ws(stmts, q + 1))
                if mname != "message":
                    raise _JSExprFail("F849 not a message read")
                if kind != "msg":
                    raise _JSExprFail("F849 message read on string")
                out.append(thrown)
                j = q
            elif q < n and stmts[q] == "[":
                q = _js_skip_ws(stmts, q + 1)
                if q >= n or stmts[q] not in "'\"":
                    raise _JSExprFail("F849 bracket not a string")
                mname, q = _js_parse_string(stmts, q)
                if mname != "message":
                    raise _JSExprFail("F849 not a message read")
                q = _js_skip_ws(stmts, q)
                q = _js_expect(stmts, q, "]")
                if kind != "msg":
                    raise _JSExprFail("F849 message read on string")
                out.append(thrown)
                j = q
            else:
                if kind != "str":
                    raise _JSExprFail("F849 bare param on object")
                out.append(thrown)
        else:
            raise _JSExprFail("F849 term not modeled")
        state["parts"] += 1
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        q = _js_skip_ws(stmts, j)
        if q < n and stmts[q] == "+":
            j = q + 1
            continue
        break
    val = "".join(out)
    if len(val) > _MAX_DECODE_BYTES:
        raise _JSExprFail("F849 concat too long")
    return val, j


def _js_parse_f849_throw_catch_iife(text, i, depth, state):
    """Parse `(function(){try{throw 'LIT';}catch(C){return ADD;}})()`
    and the `{message:'LIT'}`-throw twin (F849).

    The engine binds the catch param to the thrown value: for a
    string-literal throw the bare param is the literal; for a
    `{message:'LIT'}` throw, `C.message` / `C['message']` is the
    literal (node-exact, v24.20.0). The return additive's terms are
    plain string literals plus the param reads above; cross-combos
    (`.message` on a string throw, bare param on an object throw)
    fail closed. `catch` without a binding, `finally` clauses,
    statements before `throw`, unbound `throw x`, and `throw new
    Error(...)` (F750/F787) all fail closed. Disjoint from F750
    (requires `[new] CTOR(` after `throw`) and F787 (requires the
    two-argument cause options form) -- their throw parsers reject
    primitive/object-literal operands, and every earlier route
    fails closed on the `try{` head (red-first verified: 2 BREAK on
    the open tree), so no previously-decoded input changes
    behavior. Returns (value, next_index) or None. Never evals.
    """
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    saved_parts = state["parts"]
    saved_ops = state["ops"]
    try:
        j = _js_parse_f6xx_iife_head(text, i)
        if j is None:
            raise _JSExprFail("F849 not our head")
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        n = len(stmts)
        sj = _js_skip_ws(stmts, 0)
        tk = _js_match_kw(stmts, sj, "try")
        if tk is None:
            raise _JSExprFail("F849 no try")
        sj = _js_skip_ws(stmts, tk)
        sj = _js_expect(stmts, sj, "{")
        th = _js_match_kw(stmts, _js_skip_ws(stmts, sj), "throw")
        if th is None:
            raise _JSExprFail("F849 no throw")
        kind, thrown, sj = _js_f849_parse_throw_operand(
            stmts, _js_skip_ws(stmts, th), depth, state)
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ";")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "}")
        ck = _js_match_kw(stmts, _js_skip_ws(stmts, sj), "catch")
        if ck is None:
            raise _JSExprFail("F849 no catch")
        sj = _js_skip_ws(stmts, ck)
        sj = _js_expect(stmts, sj, "(")
        cname, sj = _js_parse_ident(stmts, _js_skip_ws(stmts, sj))
        if cname == "arguments":
            raise _JSExprFail("F849 catch param is arguments")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ")")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "{")
        # F902: `(var|let|const NAME=(CNAME|ALIAS);)*` -- the thrown
        # string copied into fresh bindings before the return.
        # Only the string-throw kind admits copies (a copy would
        # alias the thrown object for the `{message:'LIT'}` twin).
        aliases = set()
        if kind == "str":
            sj = _js_f849_parse_copy_decls(stmts, _js_skip_ws(stmts, sj),
                                           cname, aliases, state)
        rk = _js_match_kw(stmts, _js_skip_ws(stmts, sj), "return")
        if rk is None:
            raise _JSExprFail("F849 catch without return")
        val, sj = _js_f849_parse_catch_additive(
            stmts, _js_skip_ws(stmts, rk), cname, kind, thrown, state,
            aliases)
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ";")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "}")
        if _js_skip_ws(stmts, sj) != n:
            raise _JSExprFail("F849 trailing statements")
        state["ops"] += 1
        return _js_parse_f6xx_iife_tail(text, j, depth, state, val)
    except _JSExprFail:
        state["parts"] = saved_parts
        state["ops"] = saved_ops
        return None


# ---------------------------------------------------------------------------
# F903: JSON.stringify + slice laundering
# ---------------------------------------------------------------------------

def _js_f903_js_slice(s, a, b):
    """node-exact String.prototype.slice(a, b) on integer args (F903).

    v24.20.0: negatives count from the end (clamped at 0),
    out-of-range clamps to [0, len], start >= end yields "".
    Python's str slicing is identical for integer indices (both
    args are finite canonical ints by construction -- the caller
    parses them with `_js_f679_parse_int`). Never evals.
    """
    return s[a:b]


def _js_parse_f903_stringify_slice_iife(text, i, depth, state):
    """Parse `(function(){var|let|const S=JSON.stringify(VALUE);return S.slice(A,B)(+ 'LIT')*;})()` (F903).

    F903 (LOW, filed 2026-10-09 by wave-387 attack round 55): the
    decoder models JSON.parse shapes but not stringify-then-slice
    laundering:
      `(function(){var s=JSON.stringify(['f1']);return s.slice(2,-2)+'f2';})()`
      `(function(){var s=JSON.stringify({k:'f1'});return s.slice(6,-2)+'f2';})()`
    Both resolve node-exactly (v24.20.0) to the credential while
    the decoder produces zero variants.

    Node-exact desugar (v24.20.0): `JSON.stringify(VALUE)` is the
    F571 node-exact serialization (string/array/object JSON
    literals); `.slice(A,B)` on the resulting text is the
    engine's slice (see `_js_f903_js_slice`); the return additive
    is plain string-literal concatenation. The bound name must be
    fresh (not `arguments`, not reserved); the declaration and
    the return are adjacent (no rebinding -- a `S=...`
    reassignment between them fails closed). A non-literal
    stringify argument, a non-`.slice` read, non-integer slice
    args, or a non-literal additive term all fail closed
    (documented narrow scope -- rejected, never mis-decoded).
    Disjoint from every earlier route: F679's declaration grammar
    has no call-initializer production and fails closed on
    `var S=JSON.stringify(...)`; no earlier route accepts a
    JSON.stringify declaration head (red-first verified: 2 BREAK
    on the open tree), so no previously-decoded input changes
    behavior. Snapshot/restore on miss (wave-383 lesson).
    Returns (value, next_index) or None. Never evals.
    """
    n = len(text)
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    saved_parts = state["parts"]
    saved_ops = state["ops"]
    try:
        brace = _js_parse_f6xx_iife_head(text, i)
        if brace is None:
            raise _JSExprFail("F903 not our head")
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        m = len(stmts)
        sj = _js_skip_ws(stmts, 0)
        dk, dq = _js_match_decl_kw(stmts, sj)
        if dk is None:
            raise _JSExprFail("F903 not a declaration")
        sj = _js_skip_ws(stmts, dq)
        sname, sj = _js_parse_ident(stmts, sj)
        if sname == "arguments" or sname in _F611_RESERVED:
            raise _JSExprFail("F903 bad var name")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "=")
        jstr, sj = _js_parse_f571_stringify_call(
            stmts, _js_skip_ws(stmts, sj), depth, state)
        if not isinstance(jstr, str):
            raise _JSExprFail("F903 stringify not a string")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ";")
        rk = _js_match_kw(stmts, _js_skip_ws(stmts, sj), "return")
        if rk is None:
            raise _JSExprFail("F903 no return")
        sj = _js_skip_ws(stmts, rk)
        rname, sj = _js_parse_ident(stmts, sj)
        if rname != sname:
            raise _JSExprFail("F903 slice not on the bound string")
        sj = _js_skip_ws(stmts, sj)
        if sj >= m or stmts[sj] != ".":
            raise _JSExprFail("F903 slice not a dot read")
        mname, sj = _js_parse_ident(stmts, _js_skip_ws(stmts, sj + 1))
        if mname != "slice":
            raise _JSExprFail("F903 not a slice call")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "(")
        aval, sj = _js_f679_parse_int(stmts, _js_skip_ws(stmts, sj))
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ",")
        bval, sj = _js_f679_parse_int(stmts, _js_skip_ws(stmts, sj))
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ")")
        out = _js_f903_js_slice(jstr, aval, bval)
        state["parts"] += 1  # the slice is obfuscation-shaped
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        sj = _js_skip_ws(stmts, sj)
        while sj < m and stmts[sj] == "+":
            sj = _js_skip_ws(stmts, sj + 1)
            if sj >= m or stmts[sj] not in "'\"":
                raise _JSExprFail("F903 term not a literal")
            lit, sj = _js_parse_string(stmts, sj)
            if not isinstance(lit, str) or isinstance(lit, _JSNumStr):
                raise _JSExprFail("F903 term not plain")
            if len(out) + len(lit) > _MAX_DECODE_BYTES:
                raise _JSExprFail("F903 concat too long")
            out += lit
            state["parts"] += 1
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
            sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, ";")
        if _js_skip_ws(stmts, sj) != m:
            raise _JSExprFail("F903 trailing statements")
        state["ops"] += 1  # the iife wrapper is obfuscation-shaped
        return _js_parse_f6xx_iife_tail(text, j, depth, state, out)
    except _JSExprFail:
        state["parts"] = saved_parts
        state["ops"] = saved_ops
        return None

def _js_f850_parse_trap_params(stmts, j):
    """Parse `(P1,P2,P3)` at stmts[j] (F850).

    Returns (names, next_index). Never evals.
    """
    n = len(stmts)
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "(")
    names = []
    for _ in range(3):
        j = _js_skip_ws(stmts, j)
        name, j = _js_parse_ident(stmts, j)
        if name == "arguments":
            raise _JSExprFail("F850 trap param is arguments")
        if name in names:
            # Duplicate params are legal in sloppy mode (last
            # binding wins), which breaks the positional T/K/V
            # model -- fail closed (spec review 2026-10-09).
            raise _JSExprFail("F850 duplicate trap param")
        names.append(name)
        j = _js_skip_ws(stmts, j)
        if len(names) < 3:
            j = _js_expect(stmts, j, ",")
    j = _js_expect(stmts, j, ")")
    return names, j


def _js_f850_parse_trap_body(stmts, j, params, state):
    """Parse `{T[K]=V[+'LIT'];[return true|false;]}` at stmts[j]
    (F850).

    T/K/V are the trap's first/second/third params. The write
    stores the assigned value (with the optional literal suffix
    appended) into the tracked target; a missing return is the
    F675 idiom (the block returns undefined, falsy -- same sloppy-
    mode semantics as `return false`). Returns (append_or_None,
    next_index) past the body's closing brace. Never evals.
    """
    t, k, v = params
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "{")
    j = _js_skip_ws(stmts, j)
    t0, j = _js_parse_ident(stmts, j)
    if t0 != t:
        raise _JSExprFail("F850 trap write not on target")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "[")
    k0, j = _js_parse_ident(stmts, _js_skip_ws(stmts, j))
    if k0 != k:
        raise _JSExprFail("F850 trap write not on key")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "]")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "=")
    j = _js_skip_ws(stmts, j)
    v0, j = _js_parse_ident(stmts, j)
    if v0 != v:
        raise _JSExprFail("F850 trap write not the value")
    append = None
    q = _js_skip_ws(stmts, j)
    if q < len(stmts) and stmts[q] == "+":
        q = _js_skip_ws(stmts, q + 1)
        if q >= len(stmts) or stmts[q] not in "'\"":
            raise _JSExprFail("F850 trap append not a literal")
        append, q = _js_parse_string(stmts, q)
        if not isinstance(append, str) or isinstance(append, _JSNumStr):
            raise _JSExprFail("F850 trap append not plain")
        j = q
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, ";")
    j = _js_skip_ws(stmts, j)
    r = _js_match_kw(stmts, j, "return")
    if r is not None:
        # `return true;` or `return false;` (or no return at all):
        # the IIFE body is always sloppy (the decl is the first
        # statement, so no 'use strict' prologue can appear), and
        # in sloppy mode a falsy trap result leaves the
        # already-executed write in place instead of throwing
        # (node-exact, v24.20.0).
        tr = _js_match_kw(stmts, _js_skip_ws(stmts, r), "true")
        if tr is None:
            tr = _js_match_kw(stmts, _js_skip_ws(stmts, r), "false")
        if tr is None:
            raise _JSExprFail("F850 trap return not true/false")
        j = _js_skip_ws(stmts, tr)
        j = _js_expect(stmts, j, ";")
        j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "}")
    state["parts"] += 1
    if state["parts"] > _JS_EXPR_MAX_PARTS:
        raise _JSExprFail("too many parts")
    return append, j


def _js_f850_parse_concise_trap_body(stmts, j, params, state):
    """Parse `T[K]=V[+'LIT']` at stmts[j] (F850).

    The concise-arrow twin of _js_f850_parse_trap_body: no braces
    and no `return true` (the arrow returns the assigned value; a
    falsy result is sloppy-mode-harmless, so the write stands --
    node-exact, v24.20.0). Returns (append_or_None, next_index).
    Never evals.
    """
    t, k, v = params
    j = _js_skip_ws(stmts, j)
    t0, j = _js_parse_ident(stmts, j)
    if t0 != t:
        raise _JSExprFail("F850 trap write not on target")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "[")
    k0, j = _js_parse_ident(stmts, _js_skip_ws(stmts, j))
    if k0 != k:
        raise _JSExprFail("F850 trap write not on key")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "]")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "=")
    j = _js_skip_ws(stmts, j)
    v0, j = _js_parse_ident(stmts, j)
    if v0 != v:
        raise _JSExprFail("F850 trap write not the value")
    append = None
    q = _js_skip_ws(stmts, j)
    if q < len(stmts) and stmts[q] == "+":
        q = _js_skip_ws(stmts, q + 1)
        if q >= len(stmts) or stmts[q] not in "'\"":
            raise _JSExprFail("F850 trap append not a literal")
        append, q = _js_parse_string(stmts, q)
        if not isinstance(append, str) or isinstance(append, _JSNumStr):
            raise _JSExprFail("F850 trap append not plain")
        j = q
    state["parts"] += 1
    if state["parts"] > _JS_EXPR_MAX_PARTS:
        raise _JSExprFail("too many parts")
    return append, j


def _js_f850_skip_fn_name(stmts, j):
    """Skip an optional `function` name at stmts[j] (F850).

    Returns the index to parse params from: just after the name
    when a name is followed by `(`, else the input index. Never
    evals.
    """
    n = len(stmts)
    if j < n and (stmts[j].isalpha() or stmts[j] in "_$"):
        try:
            _nm, q2 = _js_parse_ident(stmts, j)
            q2 = _js_skip_ws(stmts, q2)
            if q2 < n and stmts[q2] == "(":
                return q2
        except _JSExprFail:
            pass
    return j


def _js_f850_parse_handler(stmts, j, state):
    """Parse `{set:SETFN}` at stmts[j] (F850).

    SETFN is `function[NAME](P1,P2,P3){...}`,
    `(P1,P2,P3)=>{...}`, the concise `(P1,P2,P3)=>T[K]=V[+'LIT']`,
    or the method shorthand `set(P1,P2,P3){...}`. Returns
    (append_or_None, next_index) past the handler's closing brace.
    Never evals.
    """
    n = len(stmts)
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "{")
    sk = _js_match_kw(stmts, _js_skip_ws(stmts, j), "set")
    if sk is None:
        raise _JSExprFail("F850 handler not a set trap")
    j = _js_skip_ws(stmts, sk)
    if j < n and stmts[j] == ":":
        j = _js_skip_ws(stmts, j + 1)
        fk = _js_match_kw(stmts, j, "function")
        if fk is not None:
            j = _js_f850_skip_fn_name(stmts, _js_skip_ws(stmts, fk))
            params, j = _js_f850_parse_trap_params(stmts, j)
            append, j = _js_f850_parse_trap_body(stmts, j, params,
                                                 state)
        else:
            params, j = _js_f850_parse_trap_params(stmts, j)
            j = _js_skip_ws(stmts, j)
            if j + 1 >= n or stmts[j] != "=" or stmts[j + 1] != ">":
                raise _JSExprFail("F850 not an arrow set trap")
            j = _js_skip_ws(stmts, j + 2)
            if j < n and stmts[j] == "{":
                append, j = _js_f850_parse_trap_body(stmts, j, params,
                                                     state)
            else:
                append, j = _js_f850_parse_concise_trap_body(
                    stmts, j, params, state)
    elif j < n and stmts[j] == "(":
        params, j = _js_f850_parse_trap_params(stmts, j)
        append, j = _js_f850_parse_trap_body(stmts, j, params, state)
    else:
        raise _JSExprFail("F850 set trap not a function")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "}")
    return append, j


def _js_f850_parse_write(stmts, j, pname, state):
    """Parse `PNAME.K='LIT';` / `PNAME['K']='LIT';` at stmts[j]
    (F850).

    Returns ((key, value), next_index). Never evals.
    """
    n = len(stmts)
    j = _js_skip_ws(stmts, j)
    wname, j = _js_parse_ident(stmts, j)
    if wname != pname:
        raise _JSExprFail("F850 write not on the proxy")
    j = _js_skip_ws(stmts, j)
    if j < n and stmts[j] == ".":
        key, j = _js_parse_ident(stmts, _js_skip_ws(stmts, j + 1))
    elif j < n and stmts[j] == "[":
        j = _js_skip_ws(stmts, j + 1)
        if j >= n or stmts[j] not in "'\"":
            raise _JSExprFail("F850 write key not a string")
        key, j = _js_parse_string(stmts, j)
        j = _js_skip_ws(stmts, j)
        j = _js_expect(stmts, j, "]")
    else:
        raise _JSExprFail("F850 write not a member")
    if key == "__proto__":
        raise _JSExprFail("F850 __proto__ write")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "=")
    j = _js_skip_ws(stmts, j)
    if j >= n or stmts[j] not in "'\"":
        raise _JSExprFail("F850 write value not a literal")
    lit, j = _js_parse_string(stmts, j)
    if not isinstance(lit, str) or isinstance(lit, _JSNumStr):
        raise _JSExprFail("F850 write value not plain")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, ";")
    state["parts"] += 1
    if state["parts"] > _JS_EXPR_MAX_PARTS:
        raise _JSExprFail("too many parts")
    return (key, lit), j


def _js_f850_parse_slice_int(stmts, j):
    """Parse an optionally-negative integer literal at stmts[j]
    (F850).

    Returns (int, next_index). Never evals.
    """
    n = len(stmts)
    j = _js_skip_ws(stmts, j)
    neg = False
    if j < n and stmts[j] == "-":
        neg = True
        j = _js_skip_ws(stmts, j + 1)
    k = j
    while k < n and stmts[k] in "0123456789":
        k += 1
    if k == j:
        raise _JSExprFail("F850 slice arg not an integer")
    val = int(stmts[j:k])
    return -val if neg else val, k


def _js_f850_parse_return(stmts, j, pname, stored, state):
    """Parse `PNAME.MEM[.slice(A[,B])](+'LIT')*` at stmts[j] (F850).

    With no get trap the engine reads the member through the proxy
    from the tracked target; `.slice` applies Python-slice
    semantics (verified identical to node v24.20.0, including
    negative and out-of-range indices). Returns (value,
    next_index) with the value bounded by _MAX_DECODE_BYTES. Never
    evals.
    """
    n = len(stmts)
    j = _js_skip_ws(stmts, j)
    rname, j = _js_parse_ident(stmts, j)
    if rname != pname:
        raise _JSExprFail("F850 return not the proxy")
    j = _js_skip_ws(stmts, j)
    if j < n and stmts[j] == ".":
        mname, j = _js_parse_ident(stmts, _js_skip_ws(stmts, j + 1))
    elif j < n and stmts[j] == "[":
        j = _js_skip_ws(stmts, j + 1)
        if j >= n or stmts[j] not in "'\"":
            raise _JSExprFail("F850 member not a string")
        mname, j = _js_parse_string(stmts, j)
        j = _js_skip_ws(stmts, j)
        j = _js_expect(stmts, j, "]")
    else:
        raise _JSExprFail("F850 return not a member read")
    if mname == "__proto__":
        raise _JSExprFail("F850 __proto__ read")
    if mname not in stored:
        raise _JSExprFail("F850 read of unwritten key")
    val = stored[mname]
    j = _js_skip_ws(stmts, j)
    if j < n and stmts[j] == ".":
        k = _js_skip_ws(stmts, j + 1)
        if k < n and stmts.startswith("slice", k) and \
                (k + 5 >= n or stmts[k + 5] not in _JS_IDENT_CONT):
            k = _js_skip_ws(stmts, k + 5)
            k = _js_expect(stmts, k, "(")
            a, k = _js_f850_parse_slice_int(stmts, k)
            k = _js_skip_ws(stmts, k)
            if k < n and stmts[k] == ",":
                b, k = _js_f850_parse_slice_int(
                    stmts, _js_skip_ws(stmts, k + 1))
                k = _js_skip_ws(stmts, k)
            else:
                b = None
            k = _js_expect(stmts, k, ")")
            val = val[a:b]
            state["ops"] += 1
            j = k
    while True:
        q = _js_skip_ws(stmts, j)
        if q >= n or stmts[q] != "+":
            break
        q = _js_skip_ws(stmts, q + 1)
        if q >= n or stmts[q] not in "'\"":
            raise _JSExprFail("F850 tail not a literal")
        tail, q = _js_parse_string(stmts, q)
        if not isinstance(tail, str) or isinstance(tail, _JSNumStr):
            raise _JSExprFail("F850 tail not plain")
        if len(val) + len(tail) > _MAX_DECODE_BYTES:
            raise _JSExprFail("F850 concat too long")
        val = val + tail
        state["parts"] += 1
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        j = q
    if len(val) > _MAX_DECODE_BYTES:
        raise _JSExprFail("F850 value too long")
    return val, j


def _js_parse_f850_set_trap_iife(text, i, depth, state):
    """Parse `(function(){var|let|const P=new Proxy({},{set:SETFN});
    P.K='LIT';return P.K[.slice(A[,B])](+'LIT')*;})()` (F850).

    The set trap fires on the single write statement, executing the
    modeled `T[K]=V[+'LIT']` write into the tracked (initially
    empty) target; with no get trap the return read falls through
    to the target (node-exact, v24.20.0). `return true;`,
    `return false;`, or no return are accepted -- the IIFE body is
    always sloppy (the decl is the first statement, so no
    'use strict' prologue can appear), and in sloppy mode a falsy
    trap result leaves the already-executed write in place instead
    of throwing (node-exact, v24.20.0); `__proto__` keys,
    non-empty targets, extra handler keys, non-literal writes,
    multiple writes, reads of unwritten keys, and `var Proxy`
    shadowing all fail closed. Disjoint from
    F675 (requires a var-bound target ident -- the inline `{`
    target fails its target parse), F642/F666/F670 (require
    get/apply/has keys or a literal binding section), F686/F689
    (require ownKeys/get keys), and F800 (requires a `get` handler
    key or the revocable head): every earlier route fails closed
    on these shapes (red-first verified: 2 BREAK on the open tree),
    so no previously-decoded input changes behavior. Returns
    (value, next_index) or None. Never evals.
    """
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    saved_parts = state["parts"]
    saved_ops = state["ops"]
    try:
        j = _js_parse_f6xx_iife_head(text, i)
        if j is None:
            raise _JSExprFail("F850 not our head")
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        n = len(stmts)
        sj = _js_skip_ws(stmts, 0)
        dkw, q = _js_match_decl_kw(stmts, sj)
        if dkw is None:
            raise _JSExprFail("F850 no decl")
        pname, sj = _js_parse_ident(stmts, _js_skip_ws(stmts, q))
        if pname in ("arguments", "Proxy"):
            raise _JSExprFail("F850 bad binding name")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "=")
        sj = _js_skip_ws(stmts, sj)
        nk = _js_match_kw(stmts, sj, "new")
        if nk is None:
            raise _JSExprFail("F850 not new Proxy")
        cname, nk = _js_parse_ident(stmts, _js_skip_ws(stmts, nk))
        if cname != "Proxy":
            raise _JSExprFail("F850 not a Proxy construction")
        nk = _js_skip_ws(stmts, nk)
        nk = _js_expect(stmts, nk, "(")
        nk = _js_skip_ws(stmts, nk)
        if nk >= n or stmts[nk] != "{":
            raise _JSExprFail("F850 target not inline")
        nk = _js_skip_ws(stmts, nk + 1)
        if nk >= n or stmts[nk] != "}":
            raise _JSExprFail("F850 target not empty")
        nk = _js_skip_ws(stmts, nk + 1)
        nk = _js_expect(stmts, nk, ",")
        append, nk = _js_f850_parse_handler(stmts, nk, state)
        nk = _js_skip_ws(stmts, nk)
        nk = _js_expect(stmts, nk, ")")
        nk = _js_skip_ws(stmts, nk)
        nk = _js_expect(stmts, nk, ";")
        state["parts"] += 1
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        (wkey, wlit), nk = _js_f850_parse_write(stmts, nk, pname,
                                                state)
        stored = {wkey: (wlit + append) if append else wlit}
        if len(stored[wkey]) > _MAX_DECODE_BYTES:
            raise _JSExprFail("F850 write too long")
        rk = _js_match_kw(stmts, _js_skip_ws(stmts, nk), "return")
        if rk is None:
            raise _JSExprFail("F850 no return")
        val, rq = _js_f850_parse_return(stmts, _js_skip_ws(stmts, rk),
                                        pname, stored, state)
        rq = _js_skip_ws(stmts, rq)
        rq = _js_expect(stmts, rq, ";")
        if _js_skip_ws(stmts, rq) != n:
            raise _JSExprFail("F850 trailing statements")
        state["ops"] += 1
        return _js_parse_f6xx_iife_tail(text, j, depth, state, val)
    except _JSExprFail:
        state["parts"] = saved_parts
        state["ops"] = saved_ops
        return None


# ---------------------------------------------------------------------------
# F851: nested empty-handler Proxies
# ---------------------------------------------------------------------------

def _js_f851_parse_return(stmts, j, pname, props, state):
    """Parse `PNAME.MEM(+'LIT')*` at stmts[j] (F851).

    Returns (value, next_index) with the value bounded by
    _MAX_DECODE_BYTES. Never evals.
    """
    n = len(stmts)
    j = _js_skip_ws(stmts, j)
    rname, j = _js_parse_ident(stmts, j)
    if rname != pname:
        raise _JSExprFail("F851 return not the proxy")
    j = _js_skip_ws(stmts, j)
    if j < n and stmts[j] == ".":
        mname, j = _js_parse_ident(stmts, _js_skip_ws(stmts, j + 1))
    elif j < n and stmts[j] == "[":
        j = _js_skip_ws(stmts, j + 1)
        if j >= n or stmts[j] not in "'\"":
            raise _JSExprFail("F851 member not a string")
        mname, j = _js_parse_string(stmts, j)
        j = _js_skip_ws(stmts, j)
        j = _js_expect(stmts, j, "]")
    else:
        raise _JSExprFail("F851 return not a member read")
    if mname == "__proto__":
        raise _JSExprFail("F851 __proto__ read")
    if mname not in props:
        raise _JSExprFail("F851 missing member")
    val = props[mname]
    while True:
        q = _js_skip_ws(stmts, j)
        if q >= n or stmts[q] != "+":
            break
        q = _js_skip_ws(stmts, q + 1)
        if q >= n or stmts[q] not in "'\"":
            raise _JSExprFail("F851 tail not a literal")
        tail, q = _js_parse_string(stmts, q)
        if not isinstance(tail, str) or isinstance(tail, _JSNumStr):
            raise _JSExprFail("F851 tail not plain")
        if len(val) + len(tail) > _MAX_DECODE_BYTES:
            raise _JSExprFail("F851 concat too long")
        val = val + tail
        state["parts"] += 1
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        j = q
    if len(val) > _MAX_DECODE_BYTES:
        raise _JSExprFail("F851 value too long")
    return val, j


def _js_parse_f851_nested_proxy_iife(text, i, depth, state):
    """Parse `(function(){var|let|const P=new Proxy(new Proxy(...,
    {PROPS},{}),{});return P.MEM(+'LIT')*;})()` (F851).

    2..8 nested `new Proxy` wrappers with all-empty handlers; the
    innermost target is a plain-string object literal parsed by
    _js_parse_f535_object. The engine forwards the member read
    through every empty handler to the innermost target
    (node-exact, v24.20.0). A non-empty handler anywhere, a
    non-object or non-literal innermost target, a missing or
    non-string member, `var Proxy` shadowing, or a single
    (non-nested) Proxy all fail closed. Disjoint from F800
    (requires a `get` handler key or the revocable head), F489
    (receiver-level: the target must be a `{` literal, failing on
    the inner `new`), F675/F707 (require var-bound target idents),
    and F686/F689 (require ownKeys/get handler keys) -- every
    earlier route fails closed on these shapes (red-first
    verified: 2 BREAK on the open tree), so no previously-decoded
    input changes behavior. Returns (value, next_index) or None.
    Never evals.
    """
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    saved_parts = state["parts"]
    saved_ops = state["ops"]
    try:
        j = _js_parse_f6xx_iife_head(text, i)
        if j is None:
            raise _JSExprFail("F851 not our head")
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        n = len(stmts)
        sj = _js_skip_ws(stmts, 0)
        dkw, q = _js_match_decl_kw(stmts, sj)
        if dkw is None:
            raise _JSExprFail("F851 no decl")
        pname, sj = _js_parse_ident(stmts, _js_skip_ws(stmts, q))
        if pname in ("arguments", "Proxy"):
            raise _JSExprFail("F851 bad binding name")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "=")
        total = 0
        nk = _js_skip_ws(stmts, sj)
        while True:
            kw = _js_match_kw(stmts, nk, "new")
            if kw is None:
                break
            cname, kw = _js_parse_ident(stmts, _js_skip_ws(stmts, kw))
            if cname != "Proxy":
                raise _JSExprFail("F851 not a Proxy construction")
            kw = _js_skip_ws(stmts, kw)
            kw = _js_expect(stmts, kw, "(")
            total += 1
            if total > 8:
                raise _JSExprFail("F851 too deep")
            nk = _js_skip_ws(stmts, kw)
        if total < 2:
            raise _JSExprFail("F851 not nested")
        nk = _js_skip_ws(stmts, nk)
        if nk >= n or stmts[nk] != "{":
            raise _JSExprFail("F851 target not an object")
        props, nk = _js_parse_f535_object(stmts, nk, depth, state)
        plain = {}
        for pk_, pv in props.items():
            if not isinstance(pk_, str) or \
                    not isinstance(pv, str) or \
                    isinstance(pv, _JSNumStr):
                raise _JSExprFail("F851 prop not plain string")
            plain[pk_] = pv
        for _ in range(total):
            nk = _js_skip_ws(stmts, nk)
            nk = _js_expect(stmts, nk, ",")
            nk = _js_skip_ws(stmts, nk)
            nk = _js_expect(stmts, nk, "{")
            nk = _js_skip_ws(stmts, nk)
            nk = _js_expect(stmts, nk, "}")
            nk = _js_skip_ws(stmts, nk)
            nk = _js_expect(stmts, nk, ")")
        nk = _js_skip_ws(stmts, nk)
        nk = _js_expect(stmts, nk, ";")
        state["parts"] += 1
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        rk = _js_match_kw(stmts, _js_skip_ws(stmts, nk), "return")
        if rk is None:
            raise _JSExprFail("F851 no return")
        val, rq = _js_f851_parse_return(stmts, _js_skip_ws(stmts, rk),
                                        pname, plain, state)
        rq = _js_skip_ws(stmts, rq)
        rq = _js_expect(stmts, rq, ";")
        if _js_skip_ws(stmts, rq) != n:
            raise _JSExprFail("F851 trailing statements")
        state["ops"] += 1
        return _js_parse_f6xx_iife_tail(text, j, depth, state, val)
    except _JSExprFail:
        state["parts"] = saved_parts
        state["ops"] = saved_ops
        return None


# ---------------------------------------------------------------------------
# F852: getOwnPropertyDescriptor-trap descriptor reads on an inline target
# ---------------------------------------------------------------------------

def _js_f852_parse_params(stmts, j):
    """Parse `(P1,P2)` at stmts[j] (F852).

    Returns (names, next_index). Never evals.
    """
    n = len(stmts)
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "(")
    names = []
    for _ in range(2):
        j = _js_skip_ws(stmts, j)
        name, j = _js_parse_ident(stmts, j)
        if name == "arguments":
            raise _JSExprFail("F852 trap param is arguments")
        if name in names:
            # Duplicate params are legal in sloppy mode (last
            # binding wins), which breaks the positional T/K
            # model -- fail closed (spec review 2026-10-09).
            raise _JSExprFail("F852 duplicate trap param")
        names.append(name)
        j = _js_skip_ws(stmts, j)
        if len(names) < 2:
            j = _js_expect(stmts, j, ",")
    j = _js_expect(stmts, j, ")")
    return names, j


def _js_f852_parse_desc_object(stmts, j, params, state):
    """Parse `{value:T[K],configurable:true}` (either key order) at
    stmts[j] (F852).

    The value member must read `T[K]` / `T['K']` / `T["K"]` with T/K
    the trap's first/second params; exactly the two keys `value`
    and `configurable` are allowed, and `configurable` must be the
    literal `true`. Returns ("A", keymode, next_index) past the
    closing brace, where keymode is 'param' or ('lit', key). Never
    evals.
    """
    n = len(stmts)
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "{")
    seen = {}
    for _ in range(2):
        j = _js_skip_ws(stmts, j)
        if j < n and stmts[j] in "'\"":
            kname, j = _js_parse_string(stmts, j)
        elif j < n and stmts[j] in _JS_IDENT_START:
            kname, j = _js_parse_ident(stmts, j)
        else:
            raise _JSExprFail("F852 descriptor key not modeled")
        if kname in seen:
            raise _JSExprFail("F852 dup descriptor key")
        j = _js_skip_ws(stmts, j)
        j = _js_expect(stmts, j, ":")
        j = _js_skip_ws(stmts, j)
        if kname == "value":
            t0, j = _js_parse_ident(stmts, j)
            if t0 != params[0]:
                raise _JSExprFail("F852 value not on target")
            j = _js_skip_ws(stmts, j)
            j = _js_expect(stmts, j, "[")
            j = _js_skip_ws(stmts, j)
            if j < n and stmts[j] in "'\"":
                lit, j = _js_parse_string(stmts, j)
                keymode = ("lit", lit)
            elif j < n and stmts[j] in _JS_IDENT_START:
                k0, j = _js_parse_ident(stmts, j)
                if k0 != params[1]:
                    raise _JSExprFail("F852 value not on key param")
                keymode = "param"
            else:
                raise _JSExprFail("F852 value key not modeled")
            j = _js_skip_ws(stmts, j)
            j = _js_expect(stmts, j, "]")
            seen["value"] = keymode
        elif kname == "configurable":
            ck = _js_match_kw(stmts, j, "true")
            if ck is None:
                raise _JSExprFail("F852 configurable not true")
            j = ck
            seen["configurable"] = True
        else:
            raise _JSExprFail("F852 extra descriptor key")
        j = _js_skip_ws(stmts, j)
        if len(seen) < 2:
            j = _js_expect(stmts, j, ",")
    if set(seen.keys()) != {"value", "configurable"}:
        raise _JSExprFail("F852 descriptor keys")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "}")
    state["parts"] += 1
    if state["parts"] > _JS_EXPR_MAX_PARTS:
        raise _JSExprFail("too many parts")
    return "A", seen["value"], j


def _js_f852_parse_block_body(stmts, j, params, state):
    """Parse `{BODY}` at stmts[j] (F852).

    BODY twin A: `return {value:T[K],configurable:true};`. BODY
    twin B: `var D=(Object|Reflect).getOwnPropertyDescriptor(T,K);
    return D;`. Returns (params, mode, keymode, next_index) past
    the closing brace. Never evals.
    """
    n = len(stmts)
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "{")
    rk = _js_match_kw(stmts, _js_skip_ws(stmts, j), "return")
    if rk is not None:
        mode, keymode, j = _js_f852_parse_desc_object(
            stmts, _js_skip_ws(stmts, rk), params, state)
        j = _js_skip_ws(stmts, j)
        j = _js_expect(stmts, j, ";")
        j = _js_skip_ws(stmts, j)
        j = _js_expect(stmts, j, "}")
        return params, mode, keymode, j
    dkw, j = _js_match_decl_kw(stmts, _js_skip_ws(stmts, j))
    if dkw is None:
        raise _JSExprFail("F852 body not return or decl")
    dname, j = _js_parse_ident(stmts, _js_skip_ws(stmts, j))
    if dname == "arguments":
        raise _JSExprFail("F852 fwd var is arguments")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "=")
    j = _js_skip_ws(stmts, j)
    oname, j = _js_parse_ident(stmts, j)
    if oname not in ("Object", "Reflect"):
        raise _JSExprFail("F852 fwd not Object/Reflect")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, ".")
    mname, j = _js_parse_ident(stmts, _js_skip_ws(stmts, j))
    if mname != "getOwnPropertyDescriptor":
        raise _JSExprFail("F852 fwd not gopd")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "(")
    t0, j = _js_parse_ident(stmts, _js_skip_ws(stmts, j))
    if t0 != params[0]:
        raise _JSExprFail("F852 fwd not on target param")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, ",")
    k0, j = _js_parse_ident(stmts, _js_skip_ws(stmts, j))
    if k0 != params[1]:
        raise _JSExprFail("F852 fwd not on key param")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, ")")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, ";")
    rk = _js_match_kw(stmts, _js_skip_ws(stmts, j), "return")
    if rk is None:
        raise _JSExprFail("F852 fwd without return")
    rname, j = _js_parse_ident(stmts, _js_skip_ws(stmts, rk))
    if rname != dname:
        raise _JSExprFail("F852 fwd return not the var")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, ";")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "}")
    return params, "B", None, j


def _js_f852_parse_fn_value(stmts, j, state):
    """Parse the gopd-trap function value at stmts[j] (F852).

    `function[NAME](P1,P2){BODY}`, `(P1,P2)=>{BODY}`, or the
    concise-arrow `(P1,P2)=>({value:T[K],configurable:true})`.
    Returns (params, mode, keymode, next_index) past the function.
    Never evals.
    """
    n = len(stmts)
    j = _js_skip_ws(stmts, j)
    fk = _js_match_kw(stmts, j, "function")
    if fk is not None:
        j = _js_f850_skip_fn_name(stmts, _js_skip_ws(stmts, fk))
        params, j = _js_f852_parse_params(stmts, j)
        return _js_f852_parse_block_body(stmts, j, params, state)
    params, j = _js_f852_parse_params(stmts, j)
    j = _js_skip_ws(stmts, j)
    if j + 1 >= n or stmts[j] != "=" or stmts[j + 1] != ">":
        raise _JSExprFail("F852 not an arrow gopd trap")
    j = _js_skip_ws(stmts, j + 2)
    if j < n and stmts[j] == "{":
        return _js_f852_parse_block_body(stmts, j, params, state)
    if j < n and stmts[j] == "(":
        mode, keymode, j = _js_f852_parse_desc_object(
            stmts, j + 1, params, state)
        j = _js_skip_ws(stmts, j)
        j = _js_expect(stmts, j, ")")
        if mode != "A":
            raise _JSExprFail("F852 concise not a descriptor")
        return params, mode, keymode, j
    raise _JSExprFail("F852 arrow body not modeled")


def _js_f852_parse_handler(stmts, j, state):
    """Parse `{getOwnPropertyDescriptor:GFN}` at stmts[j] (F852).

    GFN is a function expression, an arrow, or the method
    shorthand `getOwnPropertyDescriptor(P1,P2){BODY}`. Returns
    (params, mode, keymode, next_index) past the handler's closing
    brace. Never evals.
    """
    n = len(stmts)
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "{")
    gk = _js_match_kw(stmts, _js_skip_ws(stmts, j),
                      "getOwnPropertyDescriptor")
    if gk is None:
        raise _JSExprFail("F852 handler not a gopd trap")
    j = _js_skip_ws(stmts, gk)
    if j < n and stmts[j] == ":":
        params, mode, keymode, j = _js_f852_parse_fn_value(
            stmts, _js_skip_ws(stmts, j + 1), state)
    elif j < n and stmts[j] == "(":
        params, j = _js_f852_parse_params(stmts, j)
        params, mode, keymode, j = _js_f852_parse_block_body(
            stmts, j, params, state)
    else:
        raise _JSExprFail("F852 gopd trap not a function")
    j = _js_skip_ws(stmts, j)
    j = _js_expect(stmts, j, "}")
    return params, mode, keymode, j


def _js_parse_f852_gopd_trap_iife(text, i, depth, state):
    """Parse `(function(){var|let|const P=new Proxy({PROPS},
    {getOwnPropertyDescriptor:GFN});return (Object|Reflect).
    getOwnPropertyDescriptor(P,'K').value(+'LIT')*;})()` (F852).

    The gopd call invokes the trap with (target, key); twin A's
    data descriptor carries `value: target[key]` (the
    `configurable:true` literal is required, mirroring F707), and
    twin B forwards to the target's own descriptor, so `.value`
    reads the tracked target's member node-exactly (v24.20.0);
    twin B fails closed when the read key is an accessor property
    (the engine reports `.value` as `undefined` for accessors --
    decoding the getter's resolved value would mis-decode). A
    twin-A literal value key must equal the requested key; extra
    descriptor keys, non-function traps, extra handler keys,
    non-empty-target reads, and `var Proxy` shadowing all fail
    closed. Disjoint from F707 (requires a var-bound target ident
    -- the inline `{` target fails its target parse), F686 (the
    two-key ownKeys/gOPD handler fails this single-key parse),
    and F813 (requires an `Object.defineProperty` statement):
    every earlier route fails closed on these shapes (red-first
    verified: 2 BREAK on the open tree), so no previously-decoded
    input changes behavior. Returns (value, next_index) or None.
    Never evals.
    """
    if depth >= _JS_EXPR_MAX_DEPTH:
        return None
    saved_parts = state["parts"]
    saved_ops = state["ops"]
    try:
        j = _js_parse_f6xx_iife_head(text, i)
        if j is None:
            raise _JSExprFail("F852 not our head")
        brace = j
        inner_start, inner_end, j = _js_span_braced(text, brace)
        stmts = text[inner_start:inner_end]
        n = len(stmts)
        sj = _js_skip_ws(stmts, 0)
        dkw, q = _js_match_decl_kw(stmts, sj)
        if dkw is None:
            raise _JSExprFail("F852 no decl")
        pname, sj = _js_parse_ident(stmts, _js_skip_ws(stmts, q))
        if pname in ("arguments", "Proxy"):
            raise _JSExprFail("F852 bad binding name")
        sj = _js_skip_ws(stmts, sj)
        sj = _js_expect(stmts, sj, "=")
        sj = _js_skip_ws(stmts, sj)
        nk = _js_match_kw(stmts, sj, "new")
        if nk is None:
            raise _JSExprFail("F852 not new Proxy")
        cname, nk = _js_parse_ident(stmts, _js_skip_ws(stmts, nk))
        if cname != "Proxy":
            raise _JSExprFail("F852 not a Proxy construction")
        nk = _js_skip_ws(stmts, nk)
        nk = _js_expect(stmts, nk, "(")
        nk = _js_skip_ws(stmts, nk)
        if nk >= n or stmts[nk] != "{":
            raise _JSExprFail("F852 target not inline")
        props, nk = _js_parse_f535_object(stmts, nk, depth, state,
                                            accessor_aware=True)
        plain = {}
        accessors = set()
        for pk_, pv in props.items():
            if not isinstance(pk_, str):
                raise _JSExprFail("F852 prop key not plain")
            if isinstance(pv, _JSAccessor):
                # Twin B forwards the target's own descriptor: for
                # an accessor property node reports .value as
                # undefined, so twin B must fail closed on
                # accessor-valued targets (spec review 2026-10-09).
                # Twin A evaluates t[k], invoking the getter --
                # node-exact with the unwrapped value.
                accessors.add(pk_)
                pv = pv.value
            if not isinstance(pv, str) or \
                    isinstance(pv, _JSNumStr):
                raise _JSExprFail("F852 prop not plain string")
            plain[pk_] = pv
        nk = _js_skip_ws(stmts, nk)
        nk = _js_expect(stmts, nk, ",")
        _params, mode, keymode, nk = _js_f852_parse_handler(
            stmts, nk, state)
        nk = _js_skip_ws(stmts, nk)
        nk = _js_expect(stmts, nk, ")")
        nk = _js_skip_ws(stmts, nk)
        nk = _js_expect(stmts, nk, ";")
        state["parts"] += 1
        if state["parts"] > _JS_EXPR_MAX_PARTS:
            raise _JSExprFail("too many parts")
        rk = _js_match_kw(stmts, _js_skip_ws(stmts, nk), "return")
        if rk is None:
            raise _JSExprFail("F852 no return")
        q = _js_skip_ws(stmts, rk)
        oname, q = _js_parse_ident(stmts, q)
        if oname not in ("Object", "Reflect"):
            raise _JSExprFail("F852 return not Object/Reflect")
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, ".")
        mname, q = _js_parse_ident(stmts, _js_skip_ws(stmts, q))
        if mname != "getOwnPropertyDescriptor":
            raise _JSExprFail("F852 return not gopd")
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, "(")
        rname, q = _js_parse_ident(stmts, _js_skip_ws(stmts, q))
        if rname != pname:
            raise _JSExprFail("F852 gopd not on the proxy")
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, ",")
        q = _js_skip_ws(stmts, q)
        if q >= n or stmts[q] not in "'\"":
            raise _JSExprFail("F852 gopd key not a string")
        key, q = _js_parse_string(stmts, q)
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, ")")
        q = _js_skip_ws(stmts, q)
        if q < n and stmts[q] == ".":
            vname, q = _js_parse_ident(stmts, _js_skip_ws(stmts, q + 1))
            if vname != "value":
                raise _JSExprFail("F852 not a value read")
        elif q < n and stmts[q] == "[":
            q = _js_skip_ws(stmts, q + 1)
            if q >= n or stmts[q] not in "'\"":
                raise _JSExprFail("F852 value read not a string")
            vname, q = _js_parse_string(stmts, q)
            if vname != "value":
                raise _JSExprFail("F852 not a value read")
            q = _js_skip_ws(stmts, q)
            q = _js_expect(stmts, q, "]")
        else:
            raise _JSExprFail("F852 return not a value read")
        if keymode is not None and keymode != "param" and \
                keymode[1] != key:
            raise _JSExprFail("F852 literal key mismatch")
        if key not in plain:
            raise _JSExprFail("F852 key not in target")
        if mode == "B" and key in accessors:
            # Twin B forwards the target's own descriptor: for an
            # accessor property the engine reports .value as
            # undefined, so decoding the getter's resolved value
            # would mis-decode -- fail closed (spec review
            # 2026-10-09).
            raise _JSExprFail("F852 twin B on accessor")
        val = plain[key]
        while True:
            w = _js_skip_ws(stmts, q)
            if w >= n or stmts[w] != "+":
                break
            w = _js_skip_ws(stmts, w + 1)
            if w >= n or stmts[w] not in "'\"":
                raise _JSExprFail("F852 tail not a literal")
            tail, w = _js_parse_string(stmts, w)
            if not isinstance(tail, str) or isinstance(tail, _JSNumStr):
                raise _JSExprFail("F852 tail not plain")
            if len(val) + len(tail) > _MAX_DECODE_BYTES:
                raise _JSExprFail("F852 concat too long")
            val = val + tail
            state["parts"] += 1
            if state["parts"] > _JS_EXPR_MAX_PARTS:
                raise _JSExprFail("too many parts")
            q = w
        if len(val) > _MAX_DECODE_BYTES:
            raise _JSExprFail("F852 value too long")
        q = _js_skip_ws(stmts, q)
        q = _js_expect(stmts, q, ";")
        if _js_skip_ws(stmts, q) != n:
            raise _JSExprFail("F852 trailing statements")
        state["ops"] += 1
        return _js_parse_f6xx_iife_tail(text, j, depth, state, val)
    except _JSExprFail:
        state["parts"] = saved_parts
        state["ops"] = saved_ops
        return None



def _js_f792_parse_return_additive(text, j, mname, is_map, groups,
                                  state):
    """Parse the F792 `return` additive at text[j].

    Terms are string literals and group reads, joined by `+`:
    `M.get('K')[NUM]` for Map, `M.K[NUM]` / `M['K'][NUM]` for
    Object (cross-kind accessors throw in the engine -- fail
    closed). Returns (value, saw_read, next_index). Never evals.
    """
    n = len(text)
    out = []
    saw_read = False
    while True:
        j = _js_skip_ws(text, j)
        if j >= n:
            raise _JSExprFail("F792 return term overrun")
        if text[j] in "'\"":
            lit, j = _js_parse_string(text, j)
            if not isinstance(lit, str) or isinstance(lit, _JSNumStr):
                raise _JSExprFail("F792 return lit not plain")
            out.append(lit)
        elif text[j] in _JS_IDENT_START:
            name, q = _js_parse_ident(text, j)
            if name != mname:
                raise _JSExprFail("F792 return not the group var")
            arr = _js_f792_parse_group_read(text, q, is_map, groups)
            q = arr[1]
            out.append(arr[0])
            saw_read = True
            j = q
        else:
            raise _JSExprFail("F792 return bad term")
        _js_f792_charge(state)
        j = _js_skip_ws(text, j)
        if j < n and text[j] == "+":
            j += 1
            continue
        return "".join(out), saw_read, j


def _js_f792_parse_group_read(text, j, is_map, groups):
    """Parse one F792 group read at text[j] (past the var name).

    Returns (element, next_index). A missing group key throws in
    the engine (reading `[NUM]` off `undefined`); an out-of-range
    index yields `undefined` (non-string) -- both fail closed in
    the string-only discipline. Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, j)
    if is_map:
        # `M.get('K')[NUM]`
        if j >= n or text[j] != ".":
            raise _JSExprFail("F792 map read not .get")
        q = _js_skip_ws(text, j + 1)
        gk = _js_match_kw(text, q, "get")
        if gk is None:
            raise _JSExprFail("F792 map read not .get")
        q = _js_skip_ws(text, gk)
        q = _js_expect(text, q, "(")
        q = _js_skip_ws(text, q)
        if q >= n or text[q] not in "'\"":
            raise _JSExprFail("F792 map key not literal")
        key, q = _js_parse_string(text, q)
        q = _js_skip_ws(text, q)
        q = _js_expect(text, q, ")")
    else:
        # `M.K[NUM]` / `M['K'][NUM]`
        if j < n and text[j] == ".":
            q = _js_skip_ws(text, j + 1)
            key, q = _js_parse_ident(text, q)
        elif j < n and text[j] == "[":
            q = _js_skip_ws(text, j + 1)
            if q >= n or text[q] not in "'\"":
                raise _JSExprFail("F792 obj key not literal")
            key, q = _js_parse_string(text, q)
            q = _js_skip_ws(text, q)
            q = _js_expect(text, q, "]")
        else:
            raise _JSExprFail("F792 obj read not member")
    q = _js_skip_ws(text, q)
    q = _js_expect(text, q, "[")
    q = _js_skip_ws(text, q)
    num, q = _js_parse_decimal_literal(text, q,
                                       "F792 read index not literal")
    q = _js_skip_ws(text, q)
    q = _js_expect(text, q, "]")
    arr = groups.get(key)
    if arr is None:
        raise _JSExprFail("F792 group missing")
    if num >= len(arr):
        raise _JSExprFail("F792 read index out of range")
    return arr[num], q



# ------------------------------------------------------------------
# F807: structuredClone reads / F808: CustomEvent detail reads
# ------------------------------------------------------------------

def _js_f807_parse_nested_obj(text, j, depth, state, getters=False):
    """Parse `{K:'LIT'|{...},...}` at text[j] == '{' (F807/F808).

    A plain data-object literal with nesting: keys are identifiers
    or string literals (never `__proto__`, never numeric, never
    computed -- computed keys and `__proto__` fail closed);
    values are plain string literals (never _JSNumStr) or nested
    objects (recursive). Setters, methods, spreads, and non-literal
    values fail closed. When *getters* is true (F883), accessor
    properties of the exact form `get NAME(){return 'LIT';}` are
    modeled: node invokes the getter at structuredClone time and
    clones its value (v24.20.0 verified -- `{get k(){return
    'f1'}}` clones to `{k:'f1'}`), so the literal is stored as the
    property value; any other accessor shape (params, non-literal
    return, setters, methods) fails closed. Each property charges
    the F452 parts budget. Returns (_JSObj, next_index). Never
    evals.
    """
    n = len(text)
    if depth >= _JS_EXPR_MAX_DEPTH:
        raise _JSExprFail("F807 object too deep")
    j = _js_skip_ws(text, j + 1)
    props = {}
    if j < n and text[j] == "}":
        return _JSObj(props), j + 1
    while True:
        j = _js_skip_ws(text, j)
        if j >= n:
            raise _JSExprFail("F807 unterminated object")
        c = text[j]
        if c in "'\"":
            key, j = _js_parse_string(text, j)
            key_is_getter_head = False
        elif c in _JS_IDENT_START:
            key, j = _js_parse_ident(text, j)
            key_is_getter_head = (key == "get")
        else:
            raise _JSExprFail("F807 object key not a literal")
        if isinstance(key, _JSNumStr):
            raise _JSExprFail("F807 numeric key not modeled")
        if key == "__proto__":
            # The engine routes __proto__ through the prototype
            # setter; F776 owns that domain -- fail closed here.
            raise _JSExprFail("F807 __proto__ not modeled")
        j = _js_skip_ws(text, j)
        if (getters and key_is_getter_head and j < n
                and text[j] != ":"):
            # F883: accessor property `get NAME(){return 'LIT';}`.
            # Node-exact (v24.20.0): structuredClone invokes the
            # getter once and clones the returned value; only
            # function values throw DOMException (fail closed --
            # a non-literal return is never guessed).
            pname, j = _js_parse_ident(text, j)
            if isinstance(pname, _JSNumStr) or pname == "__proto__":
                raise _JSExprFail("F883 bad getter name")
            j = _js_skip_ws(text, j)
            j = _js_expect(text, j, "(")
            j = _js_skip_ws(text, j)
            j = _js_expect(text, j, ")")
            j = _js_skip_ws(text, j)
            j = _js_expect(text, j, "{")
            j = _js_skip_ws(text, j)
            gr = _js_match_kw(text, j, "return")
            if gr is None:
                raise _JSExprFail("F883 getter not a return")
            j = _js_skip_ws(text, gr)
            if j >= n or text[j] not in "'\"":
                raise _JSExprFail("F883 getter not a literal")
            val, j = _js_parse_string(text, j)
            if isinstance(val, _JSNumStr):
                raise _JSExprFail("F883 getter not a plain string")
            j = _js_skip_ws(text, j)
            j = _js_expect(text, j, ";")
            j = _js_skip_ws(text, j)
            j = _js_expect(text, j, "}")
            key = pname
        else:
            j = _js_expect(text, j, ":")
