        m = _js_expect(text, m, "=")
        if m < n and text[m] == "=":
            raise _JSExprFail("F807 decl1 not =")
        m = _js_skip_ws(text, m)
        if m >= n or text[m] != "{":
            raise _JSExprFail("F807 decl1 not an object")
