        m = _js_expect(text, m, "(")
        m = _js_skip_ws(text, m)
        aname, m = _js_parse_ident(text, m)
        if aname != oname:
            raise _JSExprFail("F807 clone arg not bound object")
        m = _js_skip_ws(text, m)
        m = _js_expect(text, m, ")")
        m = _js_skip_ws(text, m)
        m = _js_expect(text, m, ";")
