        sj = _js_expect(text, sj, ";")
        sj = _js_skip_ws(text, sj)
        if sj != inner_end:
            raise _JSExprFail("F723 trailing statements")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ")")
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, "(")
        j = _js_expect(text, j, ")")
