        if k >= n or text[k] != "(":
            return None
        k = _js_skip_ws(text, k + 1)
        if k >= n or text[k] != ")":
            return None  # outer params: the filed shapes take none
        k = _js_skip_ws(text, k + 1)
        if k >= n or text[k] != "{":
            return None
