        k = _js_skip_ws(text, k)
        if k < n and text[k] == ";":
            k += 1
        k = _js_skip_ws(text, k)
        if k >= n or text[k] != "}":
            return None
        k = _js_skip_ws(text, k + 1)
        if k >= n or text[k] != ")":
            return None
        k = _js_skip_ws(text, k + 1)
        if k >= n or text[k] != "(":
            return None
        k = _js_skip_ws(text, k + 1)
        if k >= n or text[k] != ")":
            return None  # outer invocation args: none
        k += 1
