                x2, q = _js_parse_ident(text, q)
                if x2 != xname:
                    raise _JSExprFail("F857 map arrow other ident")
                q = _js_skip_ws(text, q)
                q = _js_expect(text, q, ".")
                q = _js_skip_ws(text, q)
                _sg = _js_match_kw(text, q, "segment")
                if _sg is None:
                    raise _JSExprFail("F857 map arrow not .segment")
