def _js_parse_binding_source(text, i):
    """Parse a whitelisted binding source at text[i] (F495).

    Sources: `[].<ident>` (ws-tolerant) or exactly `Array.prototype`
    (ws-tolerant). Returns (canonical_source_text, next_index);
    anything else fails closed. Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, i)
    if text.startswith("[]", j):
        k = _js_skip_ws(text, j + 2)
        if k < n and text[k] == ".":
            name, k2 = _js_parse_ident(text, _js_skip_ws(text, k + 1))
            return "[]." + name, k2
        raise _JSExprFail("binding source not a member")
    if text.startswith("Array", j):
        k = j + len("Array")
        if k < n and text[k] in _JS_IDENT_CONT:
            raise _JSExprFail("binding source not Array")
        k = _js_skip_ws(text, k)
        if k < n and text[k] == ".":
            pname, k2 = _js_parse_ident(text, _js_skip_ws(text, k + 1))
            if pname != "prototype":
                raise _JSExprFail("binding source not Array.prototype")
            return "Array.prototype", k2
    raise _JSExprFail("binding source not whitelisted")


def _js_ident_tokens(text):
    """Yield (name, start, end) for identifier tokens in *text*.

    String literals ('...', "...") and // and /* */ comments are
    skipped exactly; a backtick anywhere aborts the scan by raising
    _JSExprFail (template literals are not tokenized -- over-skipping
    there is fail-safe, under-skipping would risk substituting inside
    a literal, so the F495 rewrite declines). Never evals.

    Note: this is a single linear pass with no parts/ops budget
    charge -- deliberate, since it only classifies characters (no
    parse tree, no variant expansion): O(len(text)) time, O(tokens)
    memory, and callers are bounded by _MAX_CANDIDATES on the decode
    side. No adversarial blowup is possible.
    """
    if "`" in text:
        raise _JSExprFail("template literal in binding scope")
    toks = []
    n = len(text)
    i = 0
    while i < n:
        c = text[i]
        if c in "'\"":
            q = c
            i += 1
            while i < n:
                if text[i] == "\\":
                    i += 2
                    continue
                if text[i] == q:
                    i += 1
                    break
                i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "/":
            while i < n and text[i] != "\n":
                i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "*":
            i += 2
            while i + 1 < n and not (text[i] == "*" and text[i + 1] == "/"):
                i += 1
            i += 2
            continue
        if c in _JS_IDENT_START:
            j = i + 1
            while j < n and text[j] in _JS_IDENT_CONT:
                j += 1
            toks.append((text[i:j], i, j))
            i = j
            continue
        i += 1
    return toks


def _js_bracket_map(text):
    """Map brackets in *text*: (open_to_close, close_to_open, arrow_eqs).

    open_to_close maps each opening bracket index (`(`, `[`, `{`) to
    its matching close; close_to_open is the inverse; arrow_eqs lists
    indices of `=` immediately followed by `>` (arrow functions).
    String literals and // and /* */ comments are skipped exactly;
    a backtick returns None (fail closed). Unbalanced closers are
    ignored (node would throw; the decoder fails closed elsewhere).
    No regex. Linear.
    """
    n = len(text)
    stack = []
    open_to_close = {}
    close_to_open = {}
    arrow_eqs = []
    i = 0
    while i < n:
        c = text[i]
        if c in "'\"":
            q = c
            i += 1
            while i < n:
                if text[i] == "\\":
                    i += 2
                    continue
                if text[i] == q:
                    i += 1
                    break
                i += 1
            continue
        if c == "`":
            return None
        if c == "/" and i + 1 < n and text[i + 1] == "/":
            while i < n and text[i] != "\n":
                i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "*":
            i += 2
            while i + 1 < n and not (text[i] == "*" and text[i + 1] == "/"):
                i += 1
            i += 2
            continue
        if c in "([{":
            stack.append(i)
        elif c in ")]}":
            if stack:
                o = stack.pop()
                open_to_close[o] = i
                close_to_open[i] = o
        elif c == "=" and i + 1 < n and text[i + 1] == ">":
            arrow_eqs.append(i)
        i += 1
    return (open_to_close, close_to_open, arrow_eqs)


def _js_remainder_rebinds(rest, toks, bound):
    """True if the remainder may rebind a bound name (F495) -- abort.

    Detects function/catch parameter lists, named-function bindings,
    for-loop groups, nested const/let/var declarators (incl.
    destructuring), `with` statements (F501: a `with` block dynamically
    scopes every identifier use inside it, so any substitution there
    would be node-wrong), and arrow-function parameters. Anything
    unparseable (unbalanced brackets, backtick, unknown arrow-param
    shape) returns True -- fail closed. Over-collection inside
    param/for groups is deliberate: it can only abort, never wrongly
    substitute. Method-shorthand and class methods are NOT detected
    (documented residual). No regex. Never evals.
    """
    mapped = _js_bracket_map(rest)
    if mapped is None:
        return True
    open_to_close, close_to_open, arrow_eqs = mapped
    n = len(rest)

    def _group_has_bound(open_idx):
        close_idx = open_to_close.get(open_idx)
        if close_idx is None:
            return True
        for tname, ts, _te in toks:
            if tname in bound and open_idx < ts < close_idx:
                return True
        return False

    for tname, ts, te in toks:
        if tname in ("function", "catch", "for"):
            j = te
            while j < n and rest[j] in " \t\n\r*":
                j += 1
            if tname == "function":
                # A named function binds its name in the enclosing scope.
                m = j
                while m < n and rest[m] in _JS_IDENT_CONT:
                    m += 1
                if m > j and rest[j:m] in bound:
                    return True
                j = m
                while j < n and rest[j] in " \t\n\r":
                    j += 1
            if j < n and rest[j] == "(" and _group_has_bound(j):
                return True
        elif tname in ("const", "let", "var"):
            j = te
            while j < n and rest[j] in " \t\n\r":
                j += 1
            if j < n and rest[j] in "[{":
                if _group_has_bound(j):
                    return True
            # Otherwise the first ident after the keyword is the
            # declared name (a later `= c` use is not a rebinding).
            for nt, ns, _ne in toks:
                if ns >= j and nt not in ("const", "let", "var"):
                    if nt in bound:
                        return True
                    break
        elif tname == "with":
            # `with(obj){...}` dynamically scopes identifier resolution
            # inside the block: a bound name used there may resolve to
            # the with-object's property instead of the binding, so any
            # substitution would be node-wrong (F501). A `with` not
            # preceded by `.`/`$`/word char is the statement -- `with`
            # is a reserved word, so a bare token can only be the
            # statement (a property named `with`, e.g. `x.with`, is
            # preceded by `.` and left alone).
            if ts == 0 or not (rest[ts - 1] in _JS_IDENT_CONT or
                               rest[ts - 1] in ".$"):
                return True
    for eq in arrow_eqs:
        j = eq - 1
        while j >= 0 and rest[j] in " \t\n\r":
            j -= 1
        if j >= 0 and rest[j] == ")":
            o = close_to_open.get(j)
            if o is None or _group_has_bound(o):
                return True
        elif j >= 0 and rest[j] in _JS_IDENT_CONT:
            m = j
            while m >= 0 and rest[m] in _JS_IDENT_CONT:
                m -= 1
            if rest[m + 1:j + 1] in bound:
                return True
        else:
            # Destructuring / unknown arrow params: fail closed.
            return True
    return False


def _js_resolve_local_bindings(text):
    """Rewrite leading local bindings to built-in members (F495).

    Matches one leading `const`/`let` statement binding identifiers
    to whitelisted built-in member expressions -- `const {m} =
    Array.prototype;`, `const {m: local} = Array.prototype;`, `let c
    = [].concat;` (comma-separated declarators allowed) -- then
    substitutes callee-position uses of the bound identifiers in the
    remainder with their bound member text, so the normal anchors
    handle `concat.call(...)` / `c.call(...)` / `K.of(...)` exactly
    as the direct forms.

    Fail-safe: any reassignment (`=`, `+=`, `++`, `--`, ...) or
    rebinding (function/catch/arrow parameters, for-loop
    declarators, nested const/let/var declarations) of a bound name
    anywhere in the remainder aborts the whole rewrite (returns
    None) -- this is conservative: a shadow inside a nested scope
    declines even outer legitimate uses (fail closed). Non-leading
    statements, `var`, non-whitelisted sources, destructuring
    defaults, and template literals in the remainder all decline.
    Method-shorthand and class methods are not scope-checked
    (documented residual). Substitution is callee-position only
    (identifier followed by `(` or `.`, not preceded by `.`/`$`/word
    char) and never touches string literals or comments. Returns the
    rewritten text, or None. Never evals.
    """
    n = len(text)
    i = _js_skip_ws(text, 0)
    for kw in ("const", "let"):
        k = i + len(kw)
        if text.startswith(kw, i) and (k >= n or text[k] not in _JS_IDENT_CONT):
            i = k
            break
    else:
        return None
    bindings = []
    try:
        while True:
            i = _js_skip_ws(text, i)
            if i < n and text[i] == "{":
                # Destructuring: {a, b: local, ...} = Array.prototype.
                i += 1
                names = []
                while True:
                    i = _js_skip_ws(text, i)
                    prop, i = _js_parse_ident(text, i)
                    i = _js_skip_ws(text, i)
                    local = prop
                    if i < n and text[i] == ":":
                        local, i = _js_parse_ident(
                            text, _js_skip_ws(text, i + 1))
                        i = _js_skip_ws(text, i)
                    names.append((local, prop))
                    if i < n and text[i] == ",":
                        i += 1
                        continue
                    if i < n and text[i] == "}":
                        i += 1
                        break
                    raise _JSExprFail("bad destructuring")
                i = _js_skip_ws(text, i)
                if i >= n or text[i] != "=":
                    raise _JSExprFail("destructure without source")
                src, i = _js_parse_binding_source(text, i + 1)
                if src != "Array.prototype":
                    raise _JSExprFail("destructure source not modeled")
                for local, prop in names:
                    bindings.append((local, src + "." + prop))
            else:
                name, i = _js_parse_ident(text, i)
                i = _js_skip_ws(text, i)
                if i >= n or text[i] != "=":
                    raise _JSExprFail("binding without source")
                src, i = _js_parse_binding_source(text, i + 1)
                bindings.append((name, src))
            i = _js_skip_ws(text, i)
            if i < n and text[i] == ",":
                i += 1
                continue
            if i < n and text[i] == ";":
                i += 1
                break
            raise _JSExprFail("binding statement not closed")
    except _JSExprFail:
        return None
    if not bindings:
        return None
    rest = text[i:]
    try:
        toks = _js_ident_tokens(rest)
    except _JSExprFail:
        return None
    names = {b[0] for b in bindings}
    # A bound name rebound anywhere in the remainder (function/catch/
    # arrow parameters, for-loop declarators, nested declarations)
    # aborts the rewrite: substituting there would be node-wrong.
    if _js_remainder_rebinds(rest, toks, names):
        return None
    # Index tokens by position for neighbor checks. NOTE (F501 lane):
    # the scans below index `rest`, so the bound is len(rest) -- the
    # earlier `n = len(text)` would walk past the end of `rest` and
    # raise IndexError when a bound token sits at the very end of the
    # remainder (fixed here; was a crash, not fail-closed).
    _rn = len(rest)
    for idx, (tname, ts, te) in enumerate(toks):
        if tname in names:
            # Reassignment of a bound name aborts: `=`, `+=`, ...,
            # `++`/`--` (prefix or postfix).
            j = te
            while j < _rn and rest[j] in " \t\n\r":
                j += 1
            nxt2 = rest[j:j + 2]
            nxt1 = rest[j:j + 1]
            if nxt1 == "=" and nxt2 not in ("==", "=>"):
                return None
            if nxt2 in ("+=", "-=", "*=", "/=", "%=", "++", "--"):
                return None
            p = ts - 1
            while p >= 0 and rest[p] in " \t\n\r":
                p -= 1
            if p >= 1 and rest[p - 1:p + 1] in ("++", "--"):
                return None
    # Substitute callee-position uses: not preceded by a word char,
    # `$`, or `.`; followed (after ws) by `(` or `.`.
    out = []
    pos = 0
    for tname, ts, te in toks:
        binding = next((b for b in bindings if b[0] == tname), None)
        if binding is None:
            continue
        if ts > 0 and (rest[ts - 1] in _JS_IDENT_CONT or
                       rest[ts - 1] in ".$"):
            continue
        j = te
        while j < _rn and rest[j] in " \t\n\r":
            j += 1
        if j >= _rn or rest[j] not in "(.":
            continue
        out.append(rest[pos:ts])
        out.append(binding[1])
        pos = te
    out.append(rest[pos:])
    # Leading whitespace is an artifact of dropping the binding
    # statement; strip it so the rewritten text anchors cleanly.
    return "".join(out).lstrip(" \t\n\r")


def _js_resolve_value_bindings(text):
    """Rewrite leading string-value bindings (F501).

    Matches one or more leading `const`/`let`/`var` statements binding
    identifiers to string literals only --
      const a='f1', b='f2';
      let a='f1'; let b='f2';
      var a='f1'; var b='f2';
    -- then substitutes every non-property, non-string, non-comment use
    of the bound identifiers in the remainder with their quoted
    literal, so additive `a+b` decodes exactly like `'f1'+'f2'`
    (node-verified, v24.20.0).

    Unlike F495 (method bindings), `var` is allowed here: with
    string-literal initializers and no reassignment anywhere in the
    remainder, hoisting cannot change any value. Unlike F495, multiple
    binding statements are consumed (the filed `let-two`/`var-two`/
    `const-two` shapes declare across two statements); the loop stops
    -- without consuming -- at the first statement that is not a pure
    value-binding statement.

    Fail-safe: any reassignment (`=`, `+=`, `++`, `--`, ...) or
    rebinding (function/catch/arrow parameters, for-loop declarators,
    nested const/let/var declarations, duplicate bound names) of a
    bound name anywhere in the remainder aborts the whole rewrite
    (returns None) -- the F495 detectors are reused verbatim.
    Non-literal initializers, destructuring, defaults, template
    literals (backtick), and missing initializers all decline; a
    statement that fails to parse as a pure binding statement is
    rewound without consuming it, and any bindings it partially
    collected are dropped, so the remainder is always scanned with
    exactly the bindings of fully-parsed statements.
    Substitution never touches string literals or comments
    (_js_ident_tokens) and never rewrites property names (a bound name
    preceded by `.`/`$`/word char is left alone -- `x.a` keeps its
    key). Returns the rewritten text, or None. Never evals.
    """
    n = len(text)
    i = _js_skip_ws(text, 0)
    bindings = []  # (name, literal_source_text)
    while True:
        i = _js_skip_ws(text, i)
        stmt_start = i
        for kw in ("const", "let", "var"):
            k = i + len(kw)
            if text.startswith(kw, i) and (
                    k >= n or text[k] not in _JS_IDENT_CONT):
                i = k
                break
        else:
            i = stmt_start
            break
        stmt_n = len(bindings)
        try:
            while True:
                i = _js_skip_ws(text, i)
                name, i = _js_parse_ident(text, i)
                i = _js_skip_ws(text, i)
                if i >= n or text[i] != "=" or text[i + 1:i + 2] in (
                        "=", ">"):
                    raise _JSExprFail("binding without initializer")
                i = _js_skip_ws(text, i + 1)
                if i >= n or text[i] not in "'\"":
                    raise _JSExprFail("binding value not a string")
                _val, lend = _js_parse_string(text, i)
                bindings.append((name, text[i:lend]))
                i = lend
                i = _js_skip_ws(text, i)
                if i < n and text[i] == ",":
                    i += 1
                    continue
                if i < n and text[i] == ";":
                    i += 1
                    break
                raise _JSExprFail("binding statement not closed")
        except _JSExprFail:
            # Not a pure value-binding statement: rewind to its start,
            # drop any bindings it partially collected, and stop
            # consuming statements (the remainder is still scanned for
            # the bindings collected so far).
            del bindings[stmt_n:]
            i = stmt_start
            break
    if not bindings:
        return None
    names = [b[0] for b in bindings]
    if len(set(names)) != len(names):
        # Duplicate declarator: later wins in the engine; declining is
        # the fail-closed choice.
        return None
    rest = text[i:]
    try:
        toks = _js_ident_tokens(rest)
    except _JSExprFail:
        return None
    bound = set(names)
    # Rebinding anywhere in the remainder aborts (F495 detector).
    if _js_remainder_rebinds(rest, toks, bound):
        return None
    _rn = len(rest)
    # Reassignment of a bound name aborts (F495 scan, rest-bounded).
    for tname, ts, te in toks:
        if tname in bound:
            j = te
            while j < _rn and rest[j] in " \t\n\r":
                j += 1
            nxt2 = rest[j:j + 2]
            nxt1 = rest[j:j + 1]
            if nxt1 == "=" and nxt2 not in ("==", "=>"):
                return None
            if nxt2 in ("+=", "-=", "*=", "/=", "%=", "++", "--"):
                return None
            p = ts - 1
            while p >= 0 and rest[p] in " \t\n\r":
                p -= 1
            if p >= 1 and rest[p - 1:p + 1] in ("++", "--"):
                return None
    # Substitute every value-position use: not preceded by a word
    # char, `$`, or `.` (property names are never rewritten).
    out = []
    pos = 0
    for tname, ts, te in toks:
        binding = next((b for b in bindings if b[0] == tname), None)
        if binding is None:
            continue
        if ts > 0 and (rest[ts - 1] in _JS_IDENT_CONT or
                       rest[ts - 1] in ".$"):
            continue
        out.append(rest[pos:ts])
        out.append(binding[1])
        pos = te
    out.append(rest[pos:])
    return "".join(out).lstrip(" \t\n\r")


def _js_f586_shift_ok(text, s):
    """Whether the `(` just left of a `new`-anchor match may open a
    grouping paren around a parenthesized new-expression receiver
    (F586).

    True only when text[s-1] == '(' (a candidate grouping paren --
    the F535 guard excludes a call's argument paren: preceded by an
    identifier char, `)`, or `]`) AND the anchor at *s* is a
    `new Map` / `new WeakRef` head (the F586 shapes). Narrow by
    construction: the plain decode at *s* is always attempted first
    by the caller, so this only fires where the plain decode failed
    closed. Never evals.
    """
    if s <= 0 or text[s - 1] != "(":
        return False
    p = s - 1
    _q = p - 1
    while _q >= 0 and text[_q] in " \t\n\r":
        _q -= 1
    if _q >= 0 and (text[_q] in _JS_IDENT_CONT
                    or text[_q] in (")", "]")):
        return False  # a call's argument paren, not a grouping paren
                      # (whitespace-tolerant: `fn (...)` is a call)
    j = _js_match_kw(text, s, "new")
    if j is None:
        return False
    j = _js_skip_ws(text, j)
    return (_js_match_kw(text, j, "Map") is not None
            or _js_match_kw(text, j, "WeakRef") is not None)


def _try_js_expr_decode_f586(text, s):
    """Decode one JS expression at match position *s*, retrying at the
    grouping paren for parenthesized new-expression receivers (F586).

    Returns (decoded, end, eff_start) -- eff_start is s-1 when the
    parenthesized form decoded, else s -- or None. The plain decode
    at *s* is always attempted first, so no previously-decodable
    input changes its variant; the paren retry only fires where the
    plain decode failed closed (the F586 shapes: the `new`-anchor
    parse fails at the grouping close-paren in _js_parse_postfix).
    The splice [eff_start:end] is always balanced (the F586 parse
    consumes its own close paren). Never evals.
    """
    r = _try_js_expr_decode(text, s)
    if r is not None:
        return r[0], r[1], s
    if _js_f586_shift_ok(text, s):
        r = _try_js_expr_decode(text, s - 1)
        if r is not None:
            return r[0], r[1], s - 1
    return None


def _try_js_expr_decode(text, start):
    """Strict static decode of one JS string expression (F430).

    Returns (decoded, end_index), or None when the run at *start* is not
    a decodable expression. Handles quoted-string '+' concatenation,
    template literals (F457: literal-only ${...} interpolation),
    String.raw`...` tag templates in every operand position (F613:
    the tag returns the template's raw strings node-exactly --
    leading, RHS-of-+, parenthesized, and array-element positions;
    ${...} interpolation fails closed),
    String.fromCharCode(...), atob('...') (F611: node-exact base64
    decode -- the fragment value feeds the concatenation composer),
    .concat(...) / .repeat(...) postfix calls, array-literal .join(sep)
    (F434), (F437) .reduce(...) / .reduceRight(...) array-assembly
    plus identity .map(...) / constant-true .filter(...) passthroughs,
    and (F443) Array(N).fill(x) construction plus .filter(Boolean)
    truthiness filtering, (F461) the no-arg .reverse() array-reversal
    step on parsed arrays, (F462) ...spread-of-array args in .concat(),
    (F446) the Array.of('frag', ...) fragment-
    list factory (string-literal args only; numeric/nested/additive args
    fail closed), (F476) the constructor-property factory path
    `[].constructor.of('frag', ...)` / `Array['of']('frag', ...)` /
    `Array["of"]('frag', ...)` -- desugared to the F446 factory
    (engine-identical; same string-literal-only arg class; `from` with
    string args throws in the engine so it fails closed; `.constructor`
    on non-`[]` receivers, non-literal member keys, and
    `Array.prototype.constructor` chains fail closed), (F454) the multi-argument Array('frag', ...) /
    new Array('frag', ...) constructor (string-literal args only; the
    single string arg is the 1-element list, exactly as the engine
    evaluates), (F455) the ws-tolerant Array.of anchor
    (whitespace around the dot, the [ \t\n\r] class the parser
    skips), (F464) .toString() on string arrays (engine-exact comma
    join) plus .replace(/,/g,'') with the literal-comma regex and a
    literal-string replacement (the /,/gi variant is comma-identical;
    general regex replace is NOT modeled; F603 extends the replace
    branch to string-literal patterns (first occurrence, matched
    literally) and flag-less regex-plain literals (first match), with
    node-exact $-pattern expansion in the replacement), (F465)
    .padStart(targetLen,padString) / .padEnd(targetLen,padString) with
    literal numeric length and literal pad string, and (F466)
    .slice(start[,end]) on string arrays with literal numeric bounds
    (negative indices and out-of-range clamps engine-exact) plus the
    .flat() identity and the literal .splice(0,2) removed-elements
    forms,
    skips), (F468) Reflect.construct(Array, <argsArray>) --
    the reflection-API factory desugared to the fragment list
    (argsArray: string-literal array literal, Array.of, or the
    F443/F454 Array constructor forms; any other target or arg class
      fails closed), (F469) Reflect.apply(Array.prototype.concat,
      <thisArg>, <argsArray>) -- the reflection-API method-application
      shape desugared to thisArg.concat(...argsArray) (target exactly
      Array.prototype.concat; thisArg/argsArray: string-literal array
      literals or Array constructor call forms; array args extended one
      level, engine-exact; any other target, arg class, or a third
      argument fails closed), and (F471) the array-copy factories
      Object.assign([], <src>) and [...<src>] -- desugared to the
      source's element list (source: any parsed string array through
      the existing parsers; target must be exactly []; multi-source
      Object.assign, nested/mixed spreads, and spread of non-arrays
      fail closed), and (F472) the `.repeat`N`` tagged-template call site
      with a literal-only count template (ToNumber + ToIntegerOrInfinity
      via _js_tag_repeat_count; interpolation, negative/infinite counts
      fail closed), (F618) `Promise.all([Promise.resolve('LIT'),...])` /
      `Promise.race([Promise.resolve('LIT')])` with a `.then` arrow
      callback -- the deterministic fulfillment is modeled statically
      (node-exact; the decoder cannot await), (F638) the sibling
      promise-continuation productions
      `Promise.reject(new Error('LIT')).catch(e=>e.message+..)`,
      `Promise.resolve('LIT').finally().then(CB)` (empty finally),
      and `Promise.allSettled([Promise.resolve('LIT'),...]).then(CB)`
      with the structural `P.map(Q=>Q.value).join('SEP')` body, and
      (F619) the
      statement-IIFE named-generator assembly
      `(function(){function* NAME(){yield 'LIT';...}<TAIL>})()` with
      the `[...NAME()].join` / `Array.from(NAME()).join` / for-of
      accumulation tails (the F494 fixed-yield discipline), and
      (F631) the async-generator twin
      `(async function(){async function* NAME(){yield 'LIT';...}<TAIL>})()`
      with for-await accumulation / single-`await IT.next()` tails
      (deterministic resolution modeled statically -- the decoder
      cannot await).
. Bounded by part, depth, codepoint, repeat, and output budgets; never
    evals; undecodable runs are ignored. A bare string literal (or an
    unjoined array literal) with no operator or call is not rewritten
    (not obfuscation-shaped).
    """
    if len(text) - start > _JS_EXPR_MAX_RUN:
        return None
    state = {"ops": 0, "parts": 0}
    try:
        val, end = _js_parse_additive(text, start, 0, state)
    except _JSExprFail:
        return None
    except RecursionError:
        return None
    if state["ops"] == 0:
        return None
    if isinstance(val, _JSArr):
        return None  # F434: bare unjoined array is not obfuscation-shaped
    if isinstance(val, _JSObj):
        return None  # F535: bare unread object literal is not
                     # obfuscation-shaped
    decoded = _ascii_printable_or_none(val)
    if decoded is None or decoded == text[start:end]:
        return None
    return decoded, end


def _try_js_expr_decode_all(text):
    """Whole-text JS string-expression scan (F444, F452).

    Decodes every strictly-decodable JS expression in *text* in one
    left-to-right pass, producing a single variant: at each
    ``_JS_EXPR_START`` match at/after the current position, attempt
    :func:`_try_js_expr_decode`; on success splice the decoded value
    in and continue past the decoded span, otherwise copy the span
    verbatim (fail closed). Matches inside an already-decoded span
    are skipped.

    This closes the F444 budget-starvation class: ``_decode_layer``
    enumerates per-match JS-expression decodes positionally
    (``[:_MAX_CANDIDATES]``) over a 2-layer budget, so attacker junk
    expressions ahead of the real one consume the enumeration window
    and the layers. One whole-text variant decodes junk and real
    expression alike in a single layer, so no positional window can
    starve the real expression out.

    Budget semantics (F452): the ``_MAX_WHOLETEXT_ITEMS`` budget
    counts only DECODE-PRODUCING attempts -- matches that decode to a
    variant and splice new text. A match that fails closed (returns
    None: not obfuscation-shaped, e.g. a bare string-literal
    statement) consumes no budget; it is copied verbatim and the scan
    continues. This is what defeats F452: 32 fail-closed bare-literal
    statements (64 quote matches) used to burn the whole 64-attempt
    budget before the real expression was reached; now they consume
    zero, and the real expression decodes.

    Why this is still a DoS guard: the decode-item budget
    (_MAX_WHOLETEXT_ITEMS) counts the actual decoding work -- each
    counted attempt splices decoded text into the output and advances
    the scan past it, so output growth and splice count stay bounded
    by 64. A second, independent cap (_MAX_WHOLETEXT_ATTEMPTS, F512)
    counts EVERY match attempt, fail-closed included: each
    _try_js_expr_decode call is internally bounded (literal/run/ops
    budgets) but thousands of such calls were not, so the total cap
    bounds aggregate work. The F444 residual stands: junk that DOES
    decode still consumes the item budget, so ~130+ decodable junk
    expressions remain a documented non-goal (each layer decodes at
    most 64, and the 2-layer budget caps the rest); the F512
    residual is 512+ fail-closed matches ahead of a real expression.

    Bounded: at most ``_MAX_WHOLETEXT_ITEMS`` decode attempts per
    scan (each attempt is ops-bounded inside
    :func:`_try_js_expr_decode`); beyond the bound the remainder is
    copied verbatim and the per-match path still tries. No new
    regexes (reuses ``_JS_EXPR_START``). Static, never executes.
    Returns None when nothing decoded.
    """
    out = []
    pos = 0
    attempts = 0
    total = 0  # F512: every match attempt counts against the DoS cap
    for m in _JS_EXPR_START.finditer(text):
        s = m.start()
        if s < pos:
            continue  # inside an already-decoded span
        if total >= _MAX_WHOLETEXT_ATTEMPTS:
            break  # F512: DoS guard -- fail-closed junk cannot buy
                   # unbounded per-match parse work
        total += 1  # F452/F512: every match attempt counts, including
                    # F567-guarded ones (fail-closed matches consume
                    # scan budget -- the guard only skips the decode)
        if text[s] in _JS_IDENT_START and not _js_left_boundary_ok(text, s):
            continue  # F567: identifier-suffixed anchor -- node throws
                      # ReferenceError; the decoder stays quiet.
        r = _try_js_expr_decode_f586(text, s)
        if r is None:
            continue  # F452: fail closed -- no variant produced, so
                      # no ITEM budget consumed; copy verbatim below
        decoded, end, _eff = r
        if end <= _eff:
            continue  # defensive: never retreat
        if attempts >= _MAX_WHOLETEXT_ITEMS:
            break
        attempts += 1  # F452: only decode-producing attempts count
                       # against the item budget
        out.append(text[pos:_eff])
        out.append(decoded)
        pos = end
    out.append(text[pos:])
    whole = "".join(out)
    return whole if whole != text else None


def _decode_layer(text):
    """One decode layer: return decoded variants of *text* (deduped)."""
    variants = []
    def _add(variant):
        if variant != text and variant not in variants:
            variants.append(variant)

    # URL-encoding layer (whole-string: %XX sequences / '+' separators).
    for dec in (unquote(text), unquote_plus(text)):
        _add(dec)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # Confusable-normalization layer (whole-string, F429): NFKC folds
    # fullwidth/compatibility confusables; zero-width joiners stripped.
    norm = _normalize_confusables(text)
    if norm is not None:
        _add(norm)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # Bidi-override normalization (whole-string, F431): strip bidi
    # controls, reverse RTL-governed runs to visual order.
    bidi = _normalize_bidi(text)
    if bidi is not None:
        _add(bidi)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # Hex runs embedded anywhere in the text.
    for m in list(_HEX_RUN.finditer(text))[:_MAX_CANDIDATES]:
        decoded = _try_hex_decode(m.group(0))
        if decoded is not None:
            _add(text[:m.start()] + decoded + text[m.end():])
    # Short hex runs (F450): strict decode with the credential-shape
    # gate -- undecodable or innocent runs are ignored, so this cannot
    # starve the candidate budget.
    for variant in _hex_short_variants(text):
        _add(variant)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # Hex runs with embedded whitespace (F451): whitespace-tolerant
    # scan; only credential-shaped strict decodes become variants.
    for variant in _hex_ws_variants(text):
        _add(variant)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # Base64 / base64url runs embedded anywhere in the text.
    for m in list(_B64_RUN.finditer(text))[:_MAX_CANDIDATES]:
        decoded = _try_b64_decode(m.group(0))
        if decoded is not None:
            _add(text[:m.start()] + decoded + text[m.end():])
    # Short base64/base64url runs (F445): strict-decode with the
    # credential-shape gate -- undecodable or innocent runs are
    # ignored, so this cannot starve the candidate budget.
    for variant in _b64_short_variants(text):
        _add(variant)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # Base64/base64url runs with embedded whitespace (F449):
    # whitespace-tolerant scan; only credential-shaped strict decodes
    # become variants.
    for variant in _b64_ws_variants(text):
        _add(variant)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # Base64/base64url runs with embedded non-whitespace junk (F456):
    # junk-tolerant scan; only credential-shaped strict decodes
    # become variants. Additive: the F449 path above is unchanged.
    for variant in _b64_junk_variants(text):
        _add(variant)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # Base32 runs embedded anywhere in the text (F8).
    for m in list(_B32_RUN.finditer(text))[:_MAX_CANDIDATES]:
        decoded = _try_b32_decode(m.group(0))
        if decoded is not None:
            _add(text[:m.start()] + decoded + text[m.end():])
    # Short base32 runs (F445): same credential-shape-gated contract.
    for variant in _b32_short_variants(text):
        _add(variant)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # JSFuck runs embedded anywhere in the text (F428): strict static
    # decode, never executed; undecodable runs are ignored.
    for m in list(_JSFUCK_RUN.finditer(text))[:_MAX_CANDIDATES]:
        decoded = _try_jsfuck_decode(m.group(0))
        if decoded is not None:
            _add(text[:m.start()] + decoded + text[m.end():])
    # F495: resolve the single leading local-binding statement (if any)
    # now; its rewritten-text variant is decoded after the whole-text
    # scan below so the pre-existing variant order is preserved
    # exactly (F441). The rewrite turns identifier callees into their
    # bound member text so `concat.call(...)` decodes exactly like
    # `Array.prototype.concat.call(...)`.
    _bound_text = _js_resolve_local_bindings(text)
    # Whole-text JS-expression scan (F444): one variant decoding every
    # strictly-decodable JS expression left-to-right, so junk
    # quoted-concat prefixes cannot starve the real expression out of
    # the positional per-match enumeration window (8) x 2-layer
    # budget. Additive: the per-match loop below is unchanged. The
    # variant composes with the other layers inside the 2-layer
    # budget exactly like the whole-text entity/escape productions.
    decoded = _try_js_expr_decode_all(text)
    if decoded is not None:
        _add(decoded)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # F495 bound-text variant: runs after the whole-text scan so the
    # pre-existing variant order is preserved exactly (F441).
    if _bound_text is not None:
        decoded = _try_js_expr_decode_all(_bound_text)
        if decoded is not None:
            _add(decoded)
            if len(variants) >= _MAX_CANDIDATES:
                return variants
    # F501: resolve leading string-value bindings (if any) the same
    # way -- the rewritten text turns `a+b` into `'f1'+'f2'` so the
    # whole-text scan decodes it. Ordered after the F495 variant to
    # preserve the pre-existing variant order exactly (F441).
    _value_text = _js_resolve_value_bindings(text)
    if _value_text is not None:
        decoded = _try_js_expr_decode_all(_value_text)
        if decoded is not None:
            _add(decoded)
            if len(variants) >= _MAX_CANDIDATES:
                return variants
    # JS string-expression runs (F430/F434/F437/F457): strict static decode of
    # quoted '+' concatenation, template literals (literal-only ${...}),
    # String.fromCharCode,
    # .concat/.repeat postfix calls, array-literal .join(sep) (F434),
    # and .reduce/.reduceRight assembly + identity .map / constant-true
    # .filter passthroughs (F437); undecodable runs are ignored.
    for m in list(_JS_EXPR_START.finditer(text))[:_MAX_CANDIDATES]:
        if text[m.start()] in _JS_IDENT_START and \
                not _js_left_boundary_ok(text, m.start()):
            continue  # F567: identifier-suffixed anchor -- node throws
                      # ReferenceError; the decoder stays quiet.
        r = _try_js_expr_decode_f586(text, m.start())
        if r is not None:
            decoded, end, _eff = r
            _add(text[:_eff] + decoded + text[end:])
    # Escaped-backslash productions (F441): collapse doubled
    # backslashes and decode the exposed escapes -- models the first
    # pass of a real double-unicode_escape parser stack. This whole-
    # text production MUST precede the per-run escape layers below:
    # on double-backslash text the per-run layers decode inside-out
    # (matching the inner escape from the second backslash), leaving
    # stray backslashes -- the F441 miss mechanism -- and their junk
    # variants would otherwise starve the _MAX_CANDIDATES budget.
    # The pure collapse composes with the escape-run layer in 2
    # layers; the collapse+decode variants keep URL-stacked
    # double-backslash shapes inside the budget. Strictly reduces
    # backslashes -- fixpoint, no loop.
    for decoded in _try_bslash_unescape_all(text):
        _add(decoded)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # Backslash-escape runs (F429): strict static \uXXXX / \xXX /
    # octal / CSS-escape decode; undecodable runs are ignored.
    for m in list(_ESC_RUN.finditer(text))[:_MAX_CANDIDATES]:
        decoded = _try_escape_decode(m.group(0))
        if decoded is not None:
            _add(text[:m.start()] + decoded + text[m.end():])
    # Backslash-escape runs, space-free CSS interpretation (F433): the
    # same runs decoded per CSS Syntax L3 4.3.7 (a non-hex code point
    # terminates the escape without being consumed; no octal fallback).
    # A run decodes under whichever genuine encoding the attacker used;
    # undecodable runs are ignored.
    for m in list(_ESC_RUN.finditer(text))[:_MAX_CANDIDATES]:
        decoded = _try_escape_decode_css_free(m.group(0))
        if decoded is not None:
            _add(text[:m.start()] + decoded + text[m.end():])
    # Numeric HTML-entity runs (F429): strict &#x..; / &#..; decode.
    for m in list(_ENTITY_RUN.finditer(text))[:_MAX_CANDIDATES]:
        decoded = _try_entity_decode(m.group(0))
        if decoded is not None:
            _add(text[:m.start()] + decoded + text[m.end():])
    # Whole-text numeric-entity decode (F436): one variant decoding
    # every entity (strict and legacy no-semicolon forms) at once, so
    # entity+base64 stacks -- a no-semicolon entity or two spaced
    # single entities poisoning a base64 run -- compose with the
    # base64 layer inside the 2-layer budget.
    decoded = _try_entity_decode_all(text)
    if decoded is not None:
        _add(decoded)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # Whole-text entity+NUL composition (F438): strip NUL bytes, then
    # decode every entity at once, so entity+NUL-interleave stacks
    # compose inside the 2-layer budget.
    decoded = _try_entity_nul_decode_all(text)
    if decoded is not None:
        _add(decoded)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # Whole-text bounded named+numeric double entity decode (F440): one
    # variant mirroring html.unescape x2 over the bounded named table
    # (amp/lt/gt/quot/apos) plus numeric entities, so double-encoded
    # entities (named-wrapped, no-semicolon named-wrapped) and their
    # base64 stacks close inside the 2-layer budget.
    decoded = _try_double_entity_decode(text)
    if decoded is not None:
        _add(decoded)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # Whole-text backslash-escape decode (F436): one variant per
    # escape-run interpretation, so spaced single escape fragments
    # poisoning a base64 run compose with the base64 layer inside the
    # 2-layer budget.
    for decoded in _try_escape_decode_all(text):
        _add(decoded)
        if len(variants) >= _MAX_CANDIDATES:
            return variants
    # UTF-16 null-interleaved runs (F429): strip the NUL bytes.
    for m in list(_UTF16N_RUN.finditer(text))[:_MAX_CANDIDATES]:
        decoded = _try_utf16_null_decode(m.group(0))
        if decoded is not None:
            _add(text[:m.start()] + decoded + text[m.end():])
    return variants


def _decoded_variants(text, max_layers=2):
    """All distinct decoded variants of *text* up to *max_layers* deep."""
    seen = {text}
    out = []
    frontier = [text]
    for _ in range(max_layers):
        nxt = []
        for t in frontier:
            for v in _decode_layer(t):
                if v not in seen:
                    seen.add(v)
                    out.append(v)
                    nxt.append(v)
        if not nxt:
            break
        frontier = nxt
    return out


def _match_credential_rules(text):
    for rule_id, rx in _CREDENTIAL_RULES:
        if rx.search(text):
            return rule_id
    return None


def _match_credential_forms(text):
    """Match the credential rules against *text* in its deterministic
    form variants (F8): as-is, whitespace-stripped, and reversed.

    These are precise transforms of a known-format credential — a match
    on any form means the text genuinely carries credential-shaped
    material, so the false-positive surface is the regexes themselves,
    not the transforms.
    """
    for candidate in (text, _WS_RUN.sub("", text), text[::-1]):
        rule = _match_credential_rules(candidate)
        if rule:
            return rule
    return None


def _find_credential_strict(text):
    """Credential regexes over *text* and its decoded variants (F2/F8).

    No entropy tripwire: this is the precise half of the check, used for
    the per-field scan and for the cross-param joined buffer.
    """
    rule = _match_credential_forms(text)
    if rule:
        return rule
    for variant in _decoded_variants(text):
        rule = _match_credential_forms(variant)
        if rule:
            return rule
    # F439: bounded base64 decode-until-fixpoint (max _MAX_B64_ROUNDS
    # rounds). Checked directly, not fed back into the layer pipeline,
    # so depth-4+ base64 stacks stay a documented non-goal.
    for variant in _b64_fixpoint_variants(text):
        rule = _match_credential_forms(variant)
        if rule:
            return rule
    return None


# ------------------------------------------------------------------ scanning

def find_credential(text):
    """Return the id of the first blocking credential rule matching *text*,
    or None. Also fires the entropy tripwire for unknown key formats.

    Encoding-aware (F2/F8/F428/F429/F430/F431): before giving up, decodes likely encodings
    (base64/base64url, base32, hex, URL-encoding, JSFuck, JS string
    expressions (F444: whole-text scan defeats junk-prefix budget
    starvation), backslash
    escapes, numeric HTML entities, double HTML-entity encoding (F440),
    UTF-16 null-interleave, confusable
    normalization incl. the Cyrillic-homoglyph map, bidi-override
    normalization -- bounded, 2 layers), short base64/base32 runs when
    the strict decode is credential-shaped (F445), plus a bounded base64
    decode-until-fixpoint pass (F439: max 3 rounds; depth-4+ base64
    stacks are a documented non-goal), and
    re-runs the credential rules on each decoded variant, in
    whitespace-stripped and reversed form as well. The entropy tripwire
    runs on the original text only (documented boundary, see module
    docstring).
    """
    rule = _find_credential_strict(text)
    if rule:
        return rule
    # Entropy tripwire: a long high-entropy token sitting near a
    # credential keyword (matched in normalized space: synonyms, spaced
    # forms, leetspeak — F16) is treated as an unknown key format.
    if _tripwire_hit(text):
        return "dlp-entropy-tripwire"
    return None


def _try_ascii_leaf(value):
    """Decode a non-string arg leaf to ASCII text, or None.

    F128 (wave-63): non-string leaves are scannable credential
    carriers — a bytes blob, or a JSON-native int array (the canonical
    byte encoding, like base64), holding a credential-shaped string is
    still that credential. Only strict ASCII decodes yield a variant
    (printable-gated, length-gated): the strict credential rules run on
    decoded leaves exactly as they do on str leaves, and the entropy
    tripwire stays on the original text (documented F2/F8 boundary).
    """
    raw = None
    if isinstance(value, (bytes, bytearray)):
        if len(value) < 8:
            return None
        raw = bytes(value)
    elif isinstance(value, (list, tuple)):
        if len(value) < 8:
            return None
        if not all(isinstance(i, int) and not isinstance(i, bool)
                   and 0 <= i <= 255 for i in value):
            return None
        raw = bytes(value)
    else:
        return None
    try:
        text = raw.decode("ascii")
    except UnicodeDecodeError:
        return None
    if not all(c.isprintable() or c in " \t\n\r" for c in text):
        return None
    return text


def _collect_strings(value, out):
    """Recursively collect every string leaf of an arg mapping.

    F128: also collects ASCII-decoded forms of bytes/bytearray leaves
    and all-int (0-255) list/tuple leaves. Dict KEYS are deliberately
    NOT collected here: this feed joins into one buffer, and key
    fragments glued onto adjacent values poison alignment-sensitive
    decoding (wave-63: keys "a"/"b" glued onto b64 halves broke the
    cross-field reassembly). Keys are scanned individually, not joined
    (see find_credential_cross_field). Used by the cross-field
    (strict-rules-only) scan, so decoded leaves never reach the
    entropy tripwire.
    """
    if isinstance(value, str):
        out.append(value)
    elif isinstance(value, (bytes, bytearray)):
        decoded = _try_ascii_leaf(value)
        if decoded is not None:
            out.append(decoded)
    elif isinstance(value, dict):
        for v in value.values():
            _collect_strings(v, out)
    elif isinstance(value, (list, tuple)):
        decoded = _try_ascii_leaf(value)
        if decoded is not None:
            out.append(decoded)
        for v in value:
            _collect_strings(v, out)


def _collect_keys(value, out):
    """Recursively collect every dict key of an arg mapping.

    F128: keys are scanned INDIVIDUALLY (never joined into the
    cross-field buffer — see _collect_strings). A credential-shaped
    string as an object key is still the credential.
    """
    if isinstance(value, dict):
        for k, v in value.items():
            if isinstance(k, str):
                out.append(k)
            elif isinstance(k, (bytes, bytearray)):
                decoded = _try_ascii_leaf(k)
                if decoded is not None:
                    out.append(decoded)
            _collect_keys(v, out)
    elif isinstance(value, (list, tuple)):
        for v in value:
            _collect_keys(v, out)


def find_credential_cross_field(args):
    """Scan the concatenation of ALL string param values (F8).

    Catches a credential chunked across params, where every chunk is
    innocent alone. Uses the strict (regex + decodings) half only — never
    the entropy tripwire — so joining fields cannot manufacture a
    heuristic hit; only a genuine known-format credential spanning the
    join blocks.

    F128: dict keys are strict-scanned individually (a credential as an
    object key is still the credential); keys never enter the joined
    buffer (glue poisoning — see _collect_strings).
    """
    parts = []
    _collect_strings(args or {}, parts)
    joined = "".join(parts)
    if joined:
        hit = _find_credential_strict(joined)
        if hit:
            return hit
    keys = []
    _collect_keys(args or {}, keys)
    for k in keys:
        hit = _find_credential_strict(k)
        if hit:
            return hit
    return None


def scrub_pii(text):
    """Redact PII in *text*. Returns (redacted_text, [rule_ids])."""
    hits = []

    def _replace(rule_id, rx, s):
        def _sub(m):
            hits.append(rule_id)
            return "[REDACTED:%s]" % rule_id
        return rx.sub(_sub, s)

    # F171: linear-time guards. The pii-email/phone/card regexes
    # backtrack quadratically on long runs of word characters with no
    # possible match (e.g. 60KB of 'd's: ~7s; 263KB: minutes), and
    # scrub_pii runs inside executor.call() BEFORE the F33 byte-cap
    # projection — an agent-controlled payload burned governor CPU
    # before the cap could deny it. Each rule only runs when its
    # trigger characters are present (a match is impossible
    # otherwise), so the whole scrub stays linear in the input length.
    # The triggers are necessary conditions of the patterns, never
    # sufficient ones: redaction behavior is unchanged.
    has_digit = any(ch.isdigit() for ch in text)  # O(n), early exit
    _triggers_ok = {
        "pii-ssn": "-" in text and has_digit,
        "pii-email": "@" in text,
        "pii-phone": has_digit,
    }
    out = text
    for rule_id, rx in _PII_RULES:
        if _triggers_ok.get(rule_id, True):
            out = _replace(rule_id, rx, out)

    def _card_sub(m):
        digits = re.sub(r"\D", "", m.group(0))
        if 13 <= len(digits) <= 19 and _luhn_ok(digits):
            hits.append("pii-card")
            return "[REDACTED:pii-card]"
        return m.group(0)

    # F171: the card pattern needs a digit to match; skip the regex
    # (and its per-candidate Luhn check) when there is none.
    if has_digit:
        out = _CARD_RE.sub(_card_sub, out)
    return out, sorted(set(hits))


def _summarize_content(value):
    raw = value if isinstance(value, str) else str(value)
    data = raw.encode("utf-8", "replace")
    return {"bytes": len(data),
            "sha256_prefix": hashlib.sha256(data).hexdigest()[:16]}


# Fields that stay readable in logs/approvals because they are the
# audit-relevant routing of the action (who/where), never its payload.
_AUDIT_FIELDS = {
    "send_email": {"to"},
    "http_post": {"url"},
    "read_file": {"path"},
    "write_file": {"path"},
    "delete_file": {"path"},
    "api_call": {"endpoint"},
}

# Payload fields whose values are summarized to {bytes, sha256} rather than
# stored verbatim: they can carry arbitrary secret material.
_SUMMARY_FIELDS = {
    "write_file": {"content"},
    "send_email": {"body"},
    "http_post": {"payload"},
}


def scan_value(text):
    """Scan one string: returns (blocked, rule_id, redacted, [pii_hits])."""
    rule = find_credential(text)
    if rule:
        return True, rule, "[BLOCKED:%s]" % rule, []
    redacted, hits = scrub_pii(text)
    return False, None, redacted, hits


def scan_tool_args(tool, args):
    """Scan a tool's argument mapping.

    Returns ``(blocked, blocking_rule, redacted_args, redactions)`` where
    ``redacted_args`` is safe to store in logs/approvals and ``redactions``
    lists every rule that fired (blocking rule first, then PII rules, then
    ``field:<tool>.<name>`` markers for summarized fields).
    """
    audit = _AUDIT_FIELDS.get(tool, set())
    summary = _SUMMARY_FIELDS.get(tool, set())
    redacted = {}
    redactions = []
    blocked = False
    blocking_rule = None
    for name, value in (args or {}).items():
        if name in summary:
            redacted[name] = _summarize_content(value)
            redactions.append("field:%s.%s" % (tool, name))
            # The summarized value is still scanned for the blocking rules
            # using the ORIGINAL value, so a secret triggers the block even
            # though only the summary is stored.
            raw = value if isinstance(value, str) else str(value)
            rule = find_credential(raw)
            if rule and not blocked:
                blocked, blocking_rule = True, rule
                redactions.insert(0, blocking_rule)
            continue
        if isinstance(value, str):
            if name in audit:
                # Audit fields (recipients, URLs, paths) stay readable: they
                # are the routing envelope the reviewer must see, and
                # subject/body redaction already covers the payload. Only
                # credential patterns in them still block (a secret pasted
                # into "to" is still a leak).
                rule = find_credential(value)
                if rule and not blocked:
                    blocked, blocking_rule = True, rule
                    redactions.insert(0, blocking_rule)
                redacted[name] = value
            else:
                is_blocked, rule, clean, hits = scan_value(value)
                redacted[name] = clean
                if is_blocked and not blocked:
                    blocked, blocking_rule = True, rule
                    redactions.insert(0, blocking_rule)
                redactions.extend(h for h in hits if h not in redactions)
        elif isinstance(value, dict):
            sub_blocked, sub_rule, sub_red, sub_hits = scan_tool_args(
                tool, {str(k): v for k, v in value.items()})
            redacted[name] = sub_red
            if sub_blocked and not blocked:
                blocked, blocking_rule = True, sub_rule
                redactions.insert(0, blocking_rule)
            redactions.extend(h for h in sub_hits if h not in redactions)
        elif isinstance(value, (bytes, bytearray)):
            # F128: a bytes/bytearray field value is a scannable
            # credential carrier — strict rules on the ASCII-decoded
            # form (the entropy tripwire stays on the original str
            # text, per the documented F2/F8 boundary). The stored
            # redaction keeps the original value untouched.
            redacted[name] = value
            decoded = _try_ascii_leaf(value)
            if decoded is not None:
                rule = _find_credential_strict(decoded)
                if rule and not blocked:
                    blocked, blocking_rule = True, rule
                    redactions.insert(0, blocking_rule)
        else:
            redacted[name] = value
    # F8: a credential chunked across params is innocent per-field. Scan
    # the joined buffer of all string values as well (strict rules only).
    if not blocked:
        rule = find_credential_cross_field(args)
        if rule:
            blocked, blocking_rule = True, rule
            redactions.insert(0, blocking_rule)
    return blocked, blocking_rule, redacted, redactions
